insert into public.fc_exercises (name, muscle_group, secondary_muscles, difficulty, exercise_type, instructions, coaching_tip, is_active, catalog_id, gif_url, image_url, equipment, created_at, updated_at)
values
('3/4 sit-up','abs',array['hip flexors','lower back']::text[],'beginner','compound',array['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.','Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.','Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.','Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'0001','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0001-2gPfomN.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0001-2gPfomN.jpg','body weight',now(),now()),
('45° side bend','abs',array['obliques']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia abajo a los lados.','Manteniendo la espalda recta y el core activado, flexiona lentamente el torso hacia un lado, bajando la mano hacia la rodilla.','Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.','Repite del otro lado.','Continúa alternando lados durante el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'0002','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0002-Hy9D21L.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0002-Hy9D21L.jpg','body weight',now(),now()),
('air bike','abs',array['hip flexors']::text[],'beginner','isolation',array['Túmbate sobre tu espalda con las manos colocadas detrás de la cabeza.','Levanta las piernas del suelo y flexiona las rodillas formando un ángulo de 90 grados.','Lleva el codo derecho hacia la rodilla izquierda mientras simultáneamente estiras la pierna derecha.','Regresa a la posición inicial y repite el movimiento del lado opuesto, llevando el codo izquierdo hacia la rodilla derecha mientras estiras la pierna izquierda.','Continúa alternando lados con un movimiento de pedaleo durante el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'0003','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0003-1ZFqTDN.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0003-1ZFqTDN.jpg','body weight',now(),now()),
('all fours squad stretch','quads',array['hamstrings','glutes']::text[],'beginner','compound',array['Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas.','Extiende una pierna hacia atrás, manteniendo la rodilla flexionada y el pie en flexión.','Baja lentamente las caderas hacia el suelo, sintiendo un estiramiento en los cuádriceps.','Mantén esta posición durante 20-30 segundos.','Cambia de pierna y repite el estiramiento del otro lado.']::text[],'Equipo: Peso corporal',true,'1512','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1512-qBcKorM.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1512-qBcKorM.jpg','body weight',now(),now()),
('alternate heel touchers','abs',array['obliques']::text[],'beginner','isolation',array['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.','Extiende los brazos hacia los lados, paralelos al suelo.','Activando el abdomen, levanta los hombros del suelo y lleva la mano derecha hacia el talón derecho.','Regresa a la posición inicial y repite del lado izquierdo, llevando la mano izquierda hacia el talón izquierdo.','Continúa alternando lados durante el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'0006','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0006-qaZVsGk.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0006-qaZVsGk.jpg','body weight',now(),now()),
('alternate lateral pulldown','lats',array['biceps','rhomboids']::text[],'beginner','compound',array['Siéntate en la máquina de cable con la espalda recta y los pies apoyados en el suelo.','Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.','Inclínate ligeramente hacia atrás y lleva las agarraderas hacia el pecho, juntando los omóplatos.','Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0007','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0007-4IKbhHV.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0007-4IKbhHV.jpg','cable',now(),now()),
('ankle circles','calves',array['ankle stabilizers']::text[],'beginner','isolation',array['Siéntate en el suelo con las piernas extendidas frente a ti.','Levanta una pierna del suelo y rota el tobillo con un movimiento circular.','Realiza el número de círculos deseado en una dirección, luego cambia a la dirección contraria.','Repite con la otra pierna.']::text[],'Equipo: Peso corporal',true,'1368','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1368-uL9CsKm.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1368-uL9CsKm.jpg','body weight',now(),now()),
('archer pull up','lats',array['biceps','forearms']::text[],'beginner','compound',array['Comienza colgándote de una barra de dominadas con un agarre prono, un poco más separado que el ancho de los hombros.','Activa el core y lleva los omóplatos hacia abajo y atrás.','Mientras te elevas, flexiona un brazo y lleva el codo hacia el costado, manteniendo el otro brazo recto.','Continúa subiendo hasta que la barbilla quede por encima de la barra y el brazo flexionado esté completamente doblado.','Bájate de nuevo con control, estirando el brazo flexionado y repitiendo el movimiento del otro lado.','Alterna los lados en cada repetición.']::text[],'Equipo: Peso corporal',true,'3293','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3293-72BC5Za.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3293-72BC5Za.jpg','body weight',now(),now()),
('archer push up','pectorals',array['triceps','shoulders','core']::text[],'beginner','compound',array['Comienza en posición de flexión de brazos con las manos un poco más separadas que el ancho de los hombros.','Extiende un brazo hacia el lado, paralelo al suelo.','Baja el cuerpo flexionando los codos, manteniendo la espalda recta y el core activado.','Empuja hacia arriba para volver a la posición inicial.','Repite del otro lado, extendiendo el brazo opuesto hacia el lado.','Continúa alternando lados durante el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'3294','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3294-A9qxk2F.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3294-A9qxk2F.jpg','body weight',now(),now()),
('arm slingers hanging bent knee legs','abs',array['shoulders','back']::text[],'beginner','compound',array['Cuélgate de una barra de dominadas con los brazos completamente extendidos y las rodillas flexionadas formando un ángulo de 90 grados.','Activa el core y levanta las rodillas hacia el pecho, acercándolas lo más posible a los codos.','Baja lentamente las piernas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'2355','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2355-uWpxD4v.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2355-uWpxD4v.jpg','body weight',now(),now()),
('arm slingers hanging straight legs','abs',array['shoulders','back']::text[],'beginner','compound',array['Cuélgate de una barra de dominadas con los brazos completamente extendidos y las piernas estiradas hacia abajo.','Activa el core y levanta las piernas hacia adelante hasta que queden paralelas al suelo.','Mantén un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'2333','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2333-PXTIwgu.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2333-PXTIwgu.jpg','body weight',now(),now()),
('arms apart circular toe touch (male)','glutes',array['hamstrings','quadriceps','calves']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.','Manteniendo las piernas rectas, flexiona el torso hacia adelante desde la cintura y lleva la mano derecha hacia los dedos de los pies.','Mientras bajas, levanta simultáneamente la pierna izquierda recta detrás de ti, manteniendo el equilibrio.','Regresa a la posición inicial y repite el movimiento llevando la mano izquierda hacia los dedos de los pies y levantando la pierna derecha detrás de ti.','Continúa alternando lados durante el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'3214','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3214-RtyAsy1.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3214-RtyAsy1.jpg','body weight',now(),now()),
('arms overhead full sit-up (male)','abs',array['hip flexors','lower back']::text[],'beginner','compound',array['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.','Extiende los brazos por encima de la cabeza, manteniéndolos rectos.','Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso quede erguido.','Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'3204','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3204-NAkmgdx.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3204-NAkmgdx.jpg','body weight',now(),now()),
('assisted chest dip (kneeling)','pectorals',array['triceps','shoulders']::text[],'beginner','compound',array['Ajusta la máquina a la altura deseada y asegura las rodillas sobre la almohadilla.','Agarra las agarraderas con las palmas hacia abajo y los brazos completamente extendidos.','Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.','Haz una pausa por un momento, luego empuja tu cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Máquina de palanca',true,'0009','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0009-PAgTVaK.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0009-PAgTVaK.jpg','leverage machine',now(),now()),
('assisted hanging knee raise','abs',array['hip flexors']::text[],'beginner','isolation',array['Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.','Activa el core y levanta las rodillas hacia el pecho, flexionando las caderas y las rodillas.','Haz una pausa por un momento en la parte superior del movimiento, apretando el abdomen.','Baja lentamente las piernas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Máquina asistida',true,'0011','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0011-03lzqwk.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0011-03lzqwk.jpg','assisted',now(),now()),
('assisted hanging knee raise with throw down','abs',array['hip flexors','lower back']::text[],'beginner','compound',array['Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.','Activa el core y levanta las rodillas hacia el pecho, manteniendo las piernas juntas.','Una vez que las rodillas estén a la altura del pecho, lanza las piernas explosivamente hacia el suelo, extendiéndolas por completo.','Deja que las piernas se balanceen de vuelta hacia arriba y repite el movimiento el número de repeticiones deseado.']::text[],'Equipo: Máquina asistida',true,'0010','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0010-8K0w2yA.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0010-8K0w2yA.jpg','assisted',now(),now()),
('assisted lying calves stretch','calves',array['hamstrings']::text[],'beginner','isolation',array['Túmbate sobre tu espalda con las piernas extendidas.','Flexiona una rodilla y coloca el pie plano sobre el suelo.','Con las manos o una toalla, jala suavemente los dedos del pie hacia tu cuerpo, sintiendo un estiramiento en la pantorrilla.','Mantén el estiramiento durante 20-30 segundos.','Suelta el estiramiento y repite con la otra pierna.']::text[],'Equipo: Máquina asistida',true,'1708','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1708-GxDwDX0.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1708-GxDwDX0.jpg','assisted',now(),now()),
('assisted lying glutes stretch','glutes',array['hamstrings']::text[],'beginner','isolation',array['Túmbate sobre tu espalda con las piernas extendidas.','Flexiona la rodilla derecha y coloca el tobillo derecho sobre el muslo izquierdo, justo encima de la rodilla.','Agarra el muslo izquierdo con ambas manos y jálalo suavemente hacia el pecho.','Mantén el estiramiento durante 20-30 segundos.','Suelta y repite del otro lado.']::text[],'Equipo: Máquina asistida',true,'1709','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1709-yn0LjwL.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1709-yn0LjwL.jpg','assisted',now(),now()),
('assisted lying gluteus and piriformis stretch','glutes',array['hamstrings']::text[],'beginner','isolation',array['Túmbate sobre tu espalda con las piernas extendidas.','Flexiona la rodilla derecha y coloca el tobillo derecho sobre el muslo izquierdo, justo encima de la rodilla.','Agarra el muslo izquierdo con ambas manos y jálalo suavemente hacia el pecho.','Mantén el estiramiento durante 20-30 segundos.','Suelta el estiramiento y repite del otro lado.']::text[],'Equipo: Máquina asistida',true,'1710','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1710-RQNVT10.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1710-RQNVT10.jpg','assisted',now(),now()),
('assisted lying leg raise with lateral throw down','abs',array['hip flexors','obliques']::text[],'beginner','compound',array['Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.','Coloca las manos debajo de los glúteos como apoyo.','Activa el abdomen y levanta las piernas del suelo, manteniéndolas rectas.','Manteniendo las piernas juntas, bájalas hacia un lado hasta que queden a pocos centímetros del suelo.','Haz una pausa por un momento, luego levanta las piernas de vuelta a la posición inicial.','Repite el movimiento hacia el otro lado.','Continúa alternando lados durante el número de repeticiones deseado.']::text[],'Equipo: Máquina asistida',true,'0012','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0012-UGhRD1A.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0012-UGhRD1A.jpg','assisted',now(),now()),
('assisted lying leg raise with throw down','abs',array['hip flexors','quadriceps']::text[],'beginner','compound',array['Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.','Coloca las manos debajo de los glúteos como apoyo.','Activa el core y levanta las piernas del suelo, manteniéndolas rectas.','Eleva las piernas hasta que queden perpendiculares al suelo.','Baja las piernas de vuelta a la posición inicial.','Simultáneamente, lanza las piernas hacia el suelo, manteniéndolas rectas.','Eleva las piernas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Máquina asistida',true,'0013','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0013-VX5YKR5.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0013-VX5YKR5.jpg','assisted',now(),now()),
('assisted motion russian twist','abs',array['obliques','lower back']::text[],'beginner','compound',array['Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo.','Sostén el balón medicinal con ambas manos frente al pecho.','Inclínate ligeramente hacia atrás, activando el abdomen y manteniendo la espalda recta.','Gira lentamente el torso hacia la derecha, llevando el balón medicinal hacia el lado derecho del cuerpo.','Haz una pausa por un momento, luego gira el torso hacia la izquierda, llevando el balón medicinal hacia el lado izquierdo del cuerpo.','Continúa alternando lados durante el número de repeticiones deseado.']::text[],'Equipo: Balón medicinal',true,'0014','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0014-r7cT9YD.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0014-r7cT9YD.jpg','medicine ball',now(),now()),
('assisted parallel close grip pull-up','lats',array['biceps','forearms']::text[],'beginner','compound',array['Ajusta la máquina al peso y la altura deseados.','Coloca las manos en las barras paralelas con un agarre cerrado, con las palmas mirándose entre sí.','Cuélgate de las barras con los brazos completamente extendidos y los pies sin tocar el suelo.','Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las barras, manteniendo los codos cerca del cuerpo.','Continúa subiendo hasta que la barbilla quede por encima de las barras.','Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Máquina de palanca',true,'0015','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0015-vrhHa6D.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0015-vrhHa6D.jpg','leverage machine',now(),now()),
('assisted prone hamstring','hamstrings',array['glutes','lower back']::text[],'beginner','compound',array['Túmbate boca abajo sobre una esterilla o un banco con las piernas completamente extendidas.','Pide a un compañero o usa una banda elástica para sujetar tus tobillos.','Activa los isquiotibiales y levanta las piernas hacia los glúteos, manteniendo las rodillas rectas.','Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Máquina asistida',true,'0016','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0016-VedGSby.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0016-VedGSby.jpg','assisted',now(),now()),
('assisted prone lying quads stretch','quads',array['hamstrings','glutes']::text[],'beginner','compound',array['Túmbate boca abajo en el suelo con las piernas extendidas.','Flexiona la rodilla izquierda y lleva la mano izquierda hacia atrás para agarrar el pie o el tobillo izquierdo.','Jala suavemente el pie izquierdo hacia los glúteos, sintiendo un estiramiento en el cuádriceps izquierdo.','Mantén el estiramiento durante 20-30 segundos, luego suelta.','Repite con la pierna derecha.']::text[],'Equipo: Máquina asistida',true,'1713','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1713-YUYAMEj.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1713-YUYAMEj.jpg','assisted',now(),now()),
('assisted prone rectus femoris stretch','abs',array['quadriceps']::text[],'beginner','isolation',array['Túmbate boca abajo en el suelo con las piernas rectas.','Flexiona la rodilla derecha y lleva la mano derecha hacia atrás para agarrar el pie o el tobillo derecho.','Jala suavemente el pie o el tobillo derecho hacia los glúteos, sintiendo un estiramiento en la parte frontal del muslo derecho.','Mantén el estiramiento durante 20-30 segundos.','Suelta y repite del otro lado.']::text[],'Equipo: Máquina asistida',true,'1714','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1714-2Ryn564.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1714-2Ryn564.jpg','assisted',now(),now()),
('assisted pull-up','lats',array['biceps','forearms']::text[],'beginner','compound',array['Ajusta la máquina a los valores de peso y altura deseados.','Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.','Cuélgate con los brazos completamente extendidos y los pies sin tocar el suelo.','Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las agarraderas, manteniendo los codos cerca del cuerpo.','Continúa subiendo hasta que la barbilla quede por encima de las agarraderas.','Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Máquina de palanca',true,'0017','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0017-kiJ4Z2K.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0017-kiJ4Z2K.jpg','leverage machine',now(),now()),
('assisted seated pectoralis major stretch with stability ball','pectorals',array['shoulders','triceps']::text[],'beginner','compound',array['Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.','Sostén un balón de estabilidad con ambas manos y extiende los brazos rectos frente a ti.','Baja lentamente el balón de estabilidad hacia el pecho, sintiendo un estiramiento en los pectorales.','Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Máquina asistida',true,'1716','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1716-RoV1Rfa.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1716-RoV1Rfa.jpg','assisted',now(),now()),
('assisted side lying adductor stretch','adductors',array['hamstrings','glutes']::text[],'beginner','compound',array['Túmbate de lado con las piernas rectas y apiladas una sobre la otra.','Flexiona ligeramente la pierna de abajo para mayor estabilidad.','Coloca el pie de arriba sobre una superficie estable, como un banco o un escalón.','Manteniendo la pierna de arriba recta, bájala lentamente hacia el suelo, sintiendo un estiramiento en la parte interna del muslo.','Mantén el estiramiento durante 20-30 segundos.','Regresa a la posición inicial y repite del otro lado.']::text[],'Equipo: Máquina asistida',true,'1712','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1712-hC6oYY5.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1712-hC6oYY5.jpg','assisted',now(),now()),
('assisted sit-up','abs',array['hip flexors']::text[],'beginner','isolation',array['Siéntate en el borde de un banco o pide a alguien que te sujete los pies.','Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.','Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.','Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.','Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Máquina asistida',true,'1758','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1758-aumB2IV.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1758-aumB2IV.jpg','assisted',now(),now()),
('assisted standing chin-up','lats',array['biceps','forearms']::text[],'beginner','compound',array['Ajusta la máquina al nivel de asistencia deseado.','Sube a la plataforma para los pies y agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.','Mantén el pecho arriba y los hombros atrás, activa el core y flexiona ligeramente las rodillas.','Levanta el cuerpo flexionando los codos y llevándolos hacia abajo, en dirección a los costados.','Continúa subiendo hasta que la barbilla quede por encima de la barra.','Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Máquina de palanca',true,'1431','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1431-7OeHptV.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1431-7OeHptV.jpg','leverage machine',now(),now()),
('assisted standing pull-up','lats',array['biceps','forearms']::text[],'beginner','compound',array['Ajusta la máquina a los valores de peso y altura deseados.','Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.','Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.','Activa los dorsales y los bíceps, y levántate hacia las agarraderas.','Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda.','Bájate lentamente de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Máquina de palanca',true,'1432','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1432-f4xtKBj.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1432-f4xtKBj.jpg','leverage machine',now(),now()),
('assisted standing triceps extension (with towel)','triceps',array['shoulders']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y sostén una toalla con ambas manos detrás de la cabeza.','Mantén los codos cerca de las orejas y la parte superior de los brazos quieta.','Extiende lentamente los antebrazos hacia arriba, apretando los tríceps en la parte superior.','Haz una pausa por un momento, luego baja lentamente la toalla de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Máquina asistida',true,'0018','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0018-7HcfMBP.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0018-7HcfMBP.jpg','assisted',now(),now()),
('assisted triceps dip (kneeling)','triceps',array['chest','shoulders']::text[],'beginner','compound',array['Ajusta la máquina al peso y la altura deseados.','Arrodíllate sobre la almohadilla frente a la máquina, con las manos sujetando las agarraderas.','Baja el cuerpo flexionando los codos, manteniendo la espalda recta y cerca de la máquina.','Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Máquina de palanca',true,'0019','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0019-J60bN17.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0019-J60bN17.jpg','leverage machine',now(),now()),
('assisted wide-grip chest dip (kneeling)','pectorals',array['triceps','shoulders']::text[],'beginner','compound',array['Ajusta la máquina a la altura deseada y asegura las rodillas sobre la almohadilla.','Agarra las agarraderas con un agarre amplio y mantén los codos ligeramente flexionados.','Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.','Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Máquina de palanca',true,'2364','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2364-PnZJIrk.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2364-PnZJIrk.jpg','leverage machine',now(),now()),
('astride jumps (male)','cardiovascular system',array['quadriceps','hamstrings','calves']::text[],'beginner','cardio',array['Ponte de pie con los pies separados a la altura de los hombros.','Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.','Salta explosivamente hacia arriba, extendiendo las piernas y los brazos.','Mientras estás en el aire, separa las piernas y lleva los brazos hacia los lados.','Aterriza suavemente con los pies separados a la altura de los hombros, flexionando las rodillas para absorber el impacto.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'3220','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3220-f9lVSSI.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3220-f9lVSSI.jpg','body weight',now(),now()),
('back and forth step','cardiovascular system',array['quadriceps','hamstrings','glutes','calves']::text[],'beginner','cardio',array['Ponte de pie con los pies separados a la altura de los hombros.','Da un paso adelante con el pie derecho, flexionando la rodilla y bajando el cuerpo hacia una posición de zancada.','Empuja con el pie derecho y da un paso atrás para regresar a la posición inicial.','Repite el movimiento con el pie izquierdo, alternando las piernas en cada paso.','Continúa dando pasos hacia adelante y hacia atrás, manteniendo un ritmo constante.','Repite durante la duración o el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'3672','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3672-fNGumX0.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3672-fNGumX0.jpg','body weight',now(),now()),
('back extension on exercise ball','spine',array['glutes','hamstrings']::text[],'beginner','compound',array['Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared u otra superficie estable.','Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.','Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones.','Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Balón de estabilidad',true,'1314','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1314-qLpO4vV.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1314-qLpO4vV.jpg','stability ball',now(),now()),
('back lever','upper back',array['biceps','forearms','core']::text[],'beginner','compound',array['Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.','Activa el core y lleva los omóplatos hacia abajo y atrás.','Flexiona las rodillas y llévalas hacia el pecho.','Levanta lentamente las piernas, manteniéndolas rectas, hasta que el cuerpo quede paralelo al suelo.','Mantén esta posición durante unos segundos, luego baja lentamente las piernas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'3297','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3297-GaSzzuh.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3297-GaSzzuh.jpg','body weight',now(),now()),
('back pec stretch','lats',array['shoulders','chest']::text[],'beginner','compound',array['Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.','Extiende los brazos rectos frente a ti, paralelos al suelo.','Cruza los brazos frente al cuerpo, con el brazo derecho sobre el brazo izquierdo.','Entrelaza los dedos y gira las palmas alejándolas del cuerpo.','Levanta lentamente los brazos hacia arriba y alejándolos del cuerpo, sintiendo un estiramiento en la espalda y el pecho.','Mantén el estiramiento durante 15-30 segundos, luego suelta.','Repite del lado opuesto.']::text[],'Equipo: Peso corporal',true,'1405','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1405-chfnQnM.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1405-chfnQnM.jpg','body weight',now(),now()),
('backward jump','quads',array['hamstrings','glutes','calves']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros.','Flexiona ligeramente las rodillas y salta hacia atrás, impulsándote con ambos pies.','Aterriza suavemente sobre la punta de los pies, flexionando las rodillas para absorber el impacto.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'1473','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1473-SaDOwk7.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1473-SaDOwk7.jpg','body weight',now(),now()),
('balance board','quads',array['calves','hamstrings','glutes']::text[],'beginner','compound',array['Coloca la tabla de equilibrio sobre una superficie plana.','Sube a la tabla de equilibrio con un pie, asegurándote de que esté centrado.','Desplaza lentamente tu peso hacia el pie que está sobre la tabla de equilibrio, manteniendo el core activado.','Mantén el equilibrio y la estabilidad mientras sostienes la posición durante el tiempo deseado.','Repite el ejercicio con el otro pie.']::text[],'Equipo: Peso corporal',true,'0020','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0020-xAySMB0.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0020-xAySMB0.jpg','body weight',now(),now()),
('band alternating biceps curl','biceps',array['forearms']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con un agarre supino, con las palmas hacia arriba.','Mantén los codos cerca de los costados y flexiona lentamente un brazo hacia el hombro, apretando el bíceps en la parte superior.','Baja el brazo de vuelta a la posición inicial y repite con el otro brazo.','Continúa alternando los brazos durante el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0968','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0968-3omWx6P.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0968-3omWx6P.jpg','band',now(),now()),
('band alternating v-up','abs',array['hip flexors']::text[],'beginner','isolation',array['Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.','Activa el abdomen y levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies.','Mientras bajas las piernas y la parte superior del cuerpo de nuevo, cambia la posición de las piernas, cruzando una sobre la otra.','Repite el movimiento, alternando la posición de las piernas en cada repetición.','Continúa durante el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0969','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0969-ztAa1RK.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0969-ztAa1RK.jpg','band',now(),now()),
('band assisted pull-up','lats',array['biceps','forearms']::text[],'beginner','compound',array['Sujeta la banda a una barra de dominadas o a un punto de anclaje resistente.','Pisa la banda y agarra la barra con las palmas mirando hacia afuera, con las manos un poco más separadas que el ancho de los hombros.','Cuélgate con los brazos completamente extendidos, manteniendo el core activado y los hombros abajo y atrás.','Sube el cuerpo hacia la barra juntando los omóplatos y llevando los codos hacia abajo, en dirección a las caderas.','Continúa subiendo hasta que la barbilla quede por encima de la barra, luego bájate lentamente de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0970','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0970-r1XNRYB.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0970-r1XNRYB.jpg','band',now(),now()),
('band assisted wheel rollerout','abs',array['lower back']::text[],'beginner','isolation',array['Arrodíllate en el suelo y sostén las agarraderas de la banda con ambas manos, con las palmas hacia abajo.','Coloca la banda en el suelo frente a ti y posiciona las manos separadas a la altura de los hombros.','Activa el core y rueda lentamente la rueda hacia adelante, extendiendo el cuerpo lo más que puedas mientras mantienes el control.','Haz una pausa por un momento en el punto más lejano, luego rueda lentamente la rueda de vuelta hacia las rodillas para regresar a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0971','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0971-zhF9lW4.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0971-zhF9lW4.jpg','band',now(),now()),
('band bench press','pectorals',array['triceps','shoulders']::text[],'beginner','compound',array['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.','Agarra las agarraderas de la banda con un agarre prono, un poco más separadas que el ancho de los hombros.','Extiende los brazos por completo, empujando las bandas alejándolas del pecho.','Baja lentamente las bandas de vuelta hacia el pecho, manteniendo los codos en un ángulo de 90 grados.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1254','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1254-khlHMqs.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1254-khlHMqs.jpg','band',now(),now()),
('band bent-over hip extension','glutes',array['hamstrings','lower back']::text[],'beginner','compound',array['Sujeta la banda a un punto de anclaje resistente a la altura del tobillo.','Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.','Da un paso atrás para generar tensión en la banda, manteniendo las rodillas ligeramente flexionadas.','Flexiona las caderas e inclínate hacia adelante, manteniendo la columna en posición neutral.','Extiende la pierna derecha recta hacia atrás, apretando los glúteos en la parte superior.','Baja la pierna derecha de vuelta y repite con la pierna izquierda.','Continúa alternando las piernas durante el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0980','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0980-wSScovH.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0980-wSScovH.jpg','band',now(),now()),
('band bicycle crunch','abs',array['hip flexors','obliques']::text[],'beginner','compound',array['Túmbate sobre tu espalda con las manos detrás de la cabeza y las rodillas flexionadas.','Levanta los pies del suelo y lleva la rodilla derecha hacia el pecho mientras simultáneamente giras el torso para llevar el codo izquierdo hacia la rodilla derecha.','Estira la pierna derecha mientras llevas la rodilla izquierda hacia el pecho y giras el torso para llevar el codo derecho hacia la rodilla izquierda.','Continúa alternando el movimiento de giro, como si estuvieras pedaleando una bicicleta, manteniendo el core activado durante todo el movimiento.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0972','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0972-tZkGYZ9.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0972-tZkGYZ9.jpg','band',now(),now()),
('band close-grip pulldown','lats',array['biceps','forearms']::text[],'beginner','compound',array['Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente.','Ponte de pie frente al punto de anclaje y agarra la banda con un agarre supino, con las manos separadas a la altura de los hombros.','Da un paso atrás para generar tensión en la banda, manteniendo los pies separados a la altura de las caderas.','Activa el core y mantén la espalda recta mientras tiras de la banda hacia el pecho, juntando los omóplatos.','Haz una pausa por un momento en la parte inferior del movimiento, luego suelta lentamente la banda de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0974','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0974-DptumMx.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0974-DptumMx.jpg','band',now(),now()),
('band close-grip push-up','triceps',array['chest','shoulders']::text[],'beginner','compound',array['Coloca una banda alrededor de la parte superior de los brazos, justo por encima de los codos.','Adopta una posición de flexión de brazos con las manos justo debajo de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.','Flexiona los codos y baja el pecho hacia el suelo, manteniendo los codos cerca de los costados.','Empuja con las palmas para extender los brazos y regresar a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0975','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0975-ufaxB52.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0975-ufaxB52.jpg','band',now(),now()),
('band concentration curl','biceps',array['forearms']::text[],'beginner','isolation',array['Siéntate en un banco o silla con las piernas separadas y los pies apoyados en el suelo.','Sostén un extremo de la banda en la mano y pisa el otro extremo con el pie del mismo lado.','Inclínate ligeramente hacia adelante y apoya el codo en la parte interna del muslo, justo encima de la rodilla.','Con la palma hacia arriba, flexiona lentamente la mano hacia el hombro, manteniendo quieta la parte superior del brazo.','Haz una pausa por un momento en la parte superior, luego baja lentamente la mano de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de lado.']::text[],'Equipo: Banda elástica',true,'0976','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0976-kmVVAfu.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0976-kmVVAfu.jpg','band',now(),now()),
('band fixed back close grip pulldown','lats',array['biceps','forearms']::text[],'beginner','compound',array['Sujeta la banda a un punto fijo por encima de ti, como una barra de dominadas o una viga resistente.','Siéntate en un banco o silla frente a la banda, con los pies apoyados en el suelo y las rodillas flexionadas.','Agarra la banda con un agarre cerrado, con las palmas hacia ti.','Mantén la espalda recta y activa el core.','Tira de la banda hacia el pecho, juntando los omóplatos.','Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales.','Suelta lentamente la banda de vuelta a la posición inicial, manteniendo el control durante todo el movimiento.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'3117','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3117-4LoWllp.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3117-4LoWllp.jpg','band',now(),now()),
('band fixed back underhand pulldown','lats',array['biceps','rhomboids','rear deltoids']::text[],'beginner','compound',array['Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza.','Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.','Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.','Da un paso atrás para generar tensión en la banda, manteniendo los brazos completamente extendidos.','Activa el core y junta los omóplatos.','Tira de la banda hacia el pecho, guiando el movimiento con los codos.','Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales.','Suelta lentamente la tensión de la banda y regresa a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'3116','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3116-ZH68exZ.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3116-ZH68exZ.jpg','band',now(),now()),
('band front lateral raise','delts',array['traps','upper back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sostén la banda frente a los muslos con las palmas hacia abajo.','Mantén los brazos rectos y levanta la banda frente a ti hasta que los brazos queden paralelos al suelo.','Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0977','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0977-sTg7iys.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0977-sTg7iys.jpg','band',now(),now()),
('band front raise','delts',array['triceps','upper back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sostén la banda frente a los muslos con las palmas hacia abajo.','Mantén los brazos rectos y levántalos lentamente hacia adelante hasta que queden paralelos al suelo.','Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0978','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0978-TFA88iB.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0978-TFA88iB.jpg','band',now(),now()),
('band hip lift','glutes',array['hamstrings','quadriceps']::text[],'beginner','compound',array['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.','Coloca una banda elástica justo por encima de las rodillas.','Activa los glúteos y los músculos del core.','Presiona los talones contra el suelo y levanta las caderas del suelo, apretando los glúteos en la parte superior.','Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1408','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1408-E4R8Hz1.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1408-E4R8Hz1.jpg','band',now(),now()),
('band horizontal pallof press','abs',array['obliques','glutes']::text[],'beginner','compound',array['Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.','Ponte de pie perpendicular al punto de anclaje con los pies separados a la altura de los hombros.','Agarra la agarradera de la banda con ambas manos y aléjate del punto de anclaje para generar tensión en la banda.','Lleva las manos hacia el pecho, manteniendo los codos flexionados y cerca del cuerpo.','Activa el core y mantén una postura estable.','Extiende los brazos rectos frente a ti, empujando la banda alejándola del cuerpo.','Mantén la posición extendida durante unos segundos, enfocándote en mantener la tensión en el core.','Lleva lentamente las manos de vuelta al pecho, resistiendo el tirón de la banda.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0979','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0979-9pa4H5m.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0979-9pa4H5m.jpg','band',now(),now()),
('band jack knife sit-up','abs',array['hip flexors']::text[],'beginner','isolation',array['Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.','Activa el abdomen y levanta las piernas y la parte superior del cuerpo simultáneamente, llevando las manos hacia los pies.','Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0981','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0981-KCBKjma.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0981-KCBKjma.jpg','band',now(),now()),
('band kneeling one arm pulldown','lats',array['biceps','rhomboids']::text[],'beginner','compound',array['Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza.','Arrodíllate y sostén la banda con una mano, con la palma hacia abajo.','Extiende el brazo por completo por encima de la cabeza, manteniendo el codo ligeramente flexionado.','Activa los dorsales y tira de la banda hacia el costado, llevando el codo hacia las costillas.','Haz una pausa por un momento en la parte inferior, luego suelta lentamente la tensión y regresa a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de lado.']::text[],'Equipo: Banda elástica',true,'0983','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0983-pmnrOp0.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0983-pmnrOp0.jpg','band',now(),now()),
('band kneeling twisting crunch','abs',array['obliques']::text[],'beginner','isolation',array['Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.','Arrodíllate de espaldas al punto de anclaje y sostén la banda con ambas manos, manteniendo los codos flexionados y cerca de los costados.','Activa el abdomen y gira lentamente el torso hacia un lado, llevando las manos hacia la cadera opuesta.','Haz una pausa por un momento, luego regresa lentamente a la posición inicial.','Repite del otro lado.','Continúa alternando lados durante el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0985','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0985-225x2Vd.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0985-225x2Vd.jpg','band',now(),now()),
('band lying hip internal rotation','glutes',array['hamstrings','quadriceps']::text[],'beginner','compound',array['Túmbate sobre tu espalda con las piernas rectas y una banda elástica enrollada alrededor de los pies.','Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies juntos.','Rota lentamente las rodillas hacia afuera, separándolas entre sí, mientras mantienes los pies juntos.','Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0984','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0984-vIICElP.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0984-vIICElP.jpg','band',now(),now()),
('band lying straight leg raise','abs',array['hip flexors']::text[],'beginner','isolation',array['Túmbate sobre tu espalda con las piernas rectas y los pies juntos.','Coloca la banda alrededor de los arcos de los pies y sostén los extremos de la banda con las manos.','Activando el abdomen, levanta ambas piernas del suelo hasta que queden perpendiculares al suelo.','Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1002','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1002-bbLR7fB.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1002-bbLR7fB.jpg','band',now(),now()),
('band one arm overhead biceps curl','biceps',array['forearms','shoulders']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y coloca un extremo de la banda bajo el pie.','Sostén el otro extremo de la banda con el brazo completamente extendido por encima de la cabeza, con la palma hacia adelante.','Manteniendo quieta la parte superior del brazo, flexiona el antebrazo hacia el hombro, apretando el bíceps.','Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de brazo.']::text[],'Equipo: Banda elástica',true,'0986','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0986-UNAB8ak.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0986-UNAB8ak.jpg','band',now(),now()),
('band one arm single leg split squat','quads',array['glutes','hamstrings']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de las caderas y coloca una banda elástica alrededor de los tobillos.','Extiende una pierna hacia adelante y apoya la parte superior del pie sobre un banco o escalón detrás de ti.','Sujétate de un apoyo con una mano para mantener el equilibrio.','Flexiona la pierna de apoyo y baja el cuerpo hacia una posición de sentadilla, manteniendo la rodilla alineada con los dedos del pie.','Empuja con el talón para regresar a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de pierna.']::text[],'Equipo: Banda elástica',true,'0987','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0987-arsYEd3.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0987-arsYEd3.jpg','band',now(),now()),
('band one arm standing low row','upper back',array['biceps','shoulders']::text[],'beginner','compound',array['Sujeta la banda a un punto de anclaje estable a la altura de la cintura.','Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.','Sostén la banda con una mano, con la palma hacia adentro, y da un paso atrás para generar tensión en la banda.','Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.','Tira de la banda hacia la cintura, juntando los omóplatos.','Haz una pausa por un momento en la parte superior del movimiento, luego suelta lentamente la banda de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de lado.']::text[],'Equipo: Banda elástica',true,'0988','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0988-km0sQC0.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0988-km0sQC0.jpg','band',now(),now()),
('band one arm twisting chest press','pectorals',array['shoulders','triceps']::text[],'beginner','compound',array['Sujeta la banda a un punto de anclaje resistente a la altura del pecho.','Ponte de pie con el costado hacia el punto de anclaje y agarra la banda con una mano.','Aléjate del punto de anclaje para generar tensión en la banda.','Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.','Lleva la mano que sostiene la banda a través del cuerpo, hacia el hombro opuesto.','Manteniendo la tensión en la banda, empuja la mano hacia adelante y alejándola del cuerpo, extendiendo el brazo.','Regresa lentamente a la posición inicial y repite el número de repeticiones deseado.','Cambia de lado y repite el ejercicio con la otra mano.']::text[],'Equipo: Banda elástica',true,'0989','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0989-c16nYGA.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0989-c16nYGA.jpg','band',now(),now()),
('band one arm twisting seated row','upper back',array['biceps','shoulders']::text[],'beginner','compound',array['Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta.','Sostén la banda con una mano y extiende el brazo completamente frente a ti.','Manteniendo la espalda recta, tira de la banda hacia el cuerpo flexionando el codo y juntando los omóplatos.','Al mismo tiempo, gira el torso hacia el lado del brazo que tira.','Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión de la banda y regresa a la posición inicial.','Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[],'Equipo: Banda elástica',true,'0990','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0990-DKBwJrL.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0990-DKBwJrL.jpg','band',now(),now()),
('band pull through','glutes',array['hamstrings','lower back']::text[],'beginner','compound',array['Sujeta una banda elástica a un punto de anclaje resistente a nivel del suelo.','Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.','Da un paso adelante para generar tensión en la banda, manteniendo las rodillas ligeramente flexionadas.','Flexiona las caderas y lleva los glúteos hacia atrás, manteniendo una ligera flexión en las rodillas.','Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.','Empuja las caderas hacia adelante y aprieta los glúteos para regresar a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0991','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0991-VtTbiP3.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0991-VtTbiP3.jpg','band',now(),now()),
('band push sit-up','abs',array['shoulders','chest']::text[],'beginner','compound',array['Sujeta la banda de forma segura a un punto de anclaje estable.','Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.','Sostén la banda con ambas manos y extiende los brazos rectos hacia el techo.','Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.','Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0992','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0992-zFzbBfL.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0992-zFzbBfL.jpg','band',now(),now()),
('band reverse fly','delts',array['upper back','trapezius']::text[],'beginner','compound',array['Sujeta la banda a un objeto fijo a la altura del pecho.','Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos frente a ti.','Mantén los brazos rectos y levántalos hacia los lados hasta que queden paralelos al suelo.','Junta los omóplatos en la parte superior del movimiento.','Baja lentamente los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0993','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0993-sTfvVsG.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0993-sTfvVsG.jpg','band',now(),now()),
('band reverse wrist curl','forearms',array['forearms']::text[],'beginner','isolation',array['Siéntate en un banco o silla con los pies apoyados en el suelo.','Sostén la banda con un agarre prono, con las palmas hacia abajo, y envuélvela alrededor de los dedos.','Apoya los antebrazos sobre los muslos, con las muñecas colgando del borde.','Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos.','Haz una pausa por un momento en la parte superior, luego baja lentamente las muñecas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0994','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0994-Ezpnw9d.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0994-Ezpnw9d.jpg','band',now(),now()),
('band seated hip internal rotation','glutes',array['hamstrings','quadriceps']::text[],'beginner','compound',array['Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.','Coloca una banda elástica alrededor de los muslos, justo por encima de las rodillas.','Mantén las rodillas flexionadas formando un ángulo de 90 grados y los pies separados a la altura de los hombros.','Activa los glúteos y rota lentamente las rodillas hacia afuera, empujando contra la resistencia de la banda.','Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0996','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0996-9gbyYKk.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0996-9gbyYKk.jpg','band',now(),now()),
('band seated twist','abs',array['obliques']::text[],'beginner','isolation',array['Siéntate en el suelo con las piernas extendidas frente a ti y la espalda recta.','Envuelve la banda alrededor de la cintura y sostén los extremos con ambas manos.','Activa el abdomen y gira lentamente el torso hacia un lado, manteniendo la espalda recta y los pies en el suelo.','Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.','Repite el giro hacia el otro lado.','Continúa alternando lados durante el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1011','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1011-S1JXDAG.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1011-S1JXDAG.jpg','band',now(),now()),
('band shoulder press','delts',array['triceps','upper back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.','Sostén la banda con las palmas hacia adelante y eleva las manos a la altura de los hombros, con los codos flexionados.','Empuja la banda por encima de la cabeza, extendiendo completamente los brazos.','Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la altura de los hombros.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0997','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0997-peAeMR3.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0997-peAeMR3.jpg','band',now(),now()),
('band shrug','traps',array['shoulders']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies, sosteniendo los extremos con las manos.','Mantén los brazos rectos y relajados, y deja que la banda cuelgue frente a los muslos.','Activa los trapecios encogiendo los hombros hacia arriba, levantando la banda lo más alto posible.','Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1018','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1018-trmte8s.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1018-trmte8s.jpg','band',now(),now()),
('band side triceps extension','triceps',array['shoulders']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos, con las palmas hacia abajo.','Extiende los brazos hacia los lados, manteniéndolos paralelos al suelo.','Flexiona lentamente los codos y lleva las manos hacia los hombros, manteniendo quieta la parte superior de los brazos.','Haz una pausa por un momento, luego extiende lentamente los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'0998','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0998-obe5LMq.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0998-obe5LMq.jpg','band',now(),now()),
('band single leg calf raise','calves',array['ankles','feet']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de las caderas y coloca la banda alrededor de la base de los dedos del pie izquierdo.','Sujétate de un objeto estable para mantener el equilibrio si es necesario.','Levanta lentamente el talón izquierdo del suelo, llevando el peso del cuerpo hacia la punta del pie.','Haz una pausa por un momento en la parte superior, luego baja lentamente el talón izquierdo de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia a la pierna derecha.']::text[],'Equipo: Banda elástica',true,'0999','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0999-9JprnPh.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0999-9JprnPh.jpg','band',now(),now()),
('band single leg reverse calf raise','calves',array['hamstrings','glutes']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de las caderas y coloca la banda alrededor de la base de los dedos del pie.','Sujétate de un objeto estable para mantener el equilibrio.','Levanta lentamente el talón del suelo, llevando el peso del cuerpo hacia la punta del pie.','Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia a la otra pierna.']::text[],'Equipo: Banda elástica',true,'1000','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1000-QsSQWbf.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1000-QsSQWbf.jpg','band',now(),now()),
('band single leg split squat','quads',array['glutes','hamstrings']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de las caderas y coloca una banda elástica alrededor de los tobillos.','Da un paso grande hacia adelante con el pie derecho y un paso más pequeño hacia atrás con el pie izquierdo.','Flexiona las rodillas y baja el cuerpo hasta que el muslo derecho quede paralelo al suelo, manteniendo la rodilla izquierda ligeramente por encima del suelo.','Empuja con el talón derecho para regresar a la posición inicial.','Repite del otro lado.']::text[],'Equipo: Banda elástica',true,'1001','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1001-y8bYM8w.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1001-y8bYM8w.jpg','band',now(),now()),
('band squat','glutes',array['quadriceps','hamstrings','calves']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, con la banda colocada justo por encima de las rodillas.','Manteniendo el pecho arriba y el core activado, lleva las caderas hacia atrás y flexiona las rodillas para bajar a una posición de sentadilla.','Asegúrate de que las rodillas se alineen con los dedos de los pies y de que el peso recaiga en los talones.','Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1004','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1004-TUZLh71.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1004-TUZLh71.jpg','band',now(),now()),
('band squat row','glutes',array['hamstrings','quadriceps','back']::text[],'beginner','compound',array['Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.','Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.','Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti.','Flexiona las rodillas y baja a una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.','Desde la posición de sentadilla, tira de las agarraderas de la banda hacia el cuerpo, juntando los omóplatos.','Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1003','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1003-w1NOByi.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1003-w1NOByi.jpg','band',now(),now()),
('band standing crunch','abs',array['obliques']::text[],'beginner','isolation',array['Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.','Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.','Sostén la banda con ambas manos y llévala hacia el pecho, manteniendo los codos flexionados y cerca del cuerpo.','Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando el pecho hacia las rodillas.','Haz una pausa por un momento en la parte más alta del movimiento, luego regresa lentamente a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1005','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1005-Kzg30R7.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1005-Kzg30R7.jpg','band',now(),now()),
('band standing rear delt row','delts',array['trapezius','rhomboids','biceps']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.','Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti.','Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.','Tira de la banda hacia el pecho, juntando los omóplatos.','Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1022','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1022-tc5dYrf.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1022-tc5dYrf.jpg','band',now(),now()),
('band standing twisting crunch','abs',array['obliques']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de la parte superior de la espalda, cruzándola frente al pecho.','Sujeta los extremos de la banda con las manos, manteniendo los codos flexionados y cerca de los costados.','Activa el abdomen y gira el torso hacia un lado, llevando el codo hacia la rodilla opuesta.','Haz una pausa breve y luego vuelve a la posición inicial.','Repite del otro lado.','Continúa alternando lados durante el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1007','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1007-euq4pwp.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1007-euq4pwp.jpg','band',now(),now()),
('band step-up','glutes',array['quadriceps','hamstrings','calves']::text[],'beginner','compound',array['Coloca una banda alrededor de los muslos, justo por encima de las rodillas.','Ponte de pie frente a un escalón o plataforma con los pies separados a la altura de las caderas.','Sube a la plataforma con el pie derecho, empujando con el talón.','Extiende la pierna izquierda hacia atrás, manteniéndola recta.','Baja el pie izquierdo de nuevo hasta el suelo.','Repite subiendo a la plataforma con el pie izquierdo.','Continúa alternando las piernas durante el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1008','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1008-d5bTEPV.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1008-d5bTEPV.jpg','band',now(),now()),
('band stiff leg deadlift','glutes',array['hamstrings','lower back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de los tobillos.','Sujeta la banda con ambas manos frente a los muslos, con las palmas mirando hacia el cuerpo.','Manteniendo la espalda recta y el core activado, flexiona las caderas y baja lentamente la parte superior del cuerpo hacia el suelo.','Mientras bajas, empuja las caderas hacia atrás y deja que las rodillas se flexionen ligeramente.','Baja la banda hacia el suelo, sintiendo un estiramiento en los isquiotibiales.','Haz una pausa breve en la posición baja, luego activa los glúteos y los isquiotibiales para levantar la parte superior del cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1009','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1009-kuMiR2T.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1009-kuMiR2T.jpg','band',now(),now()),
('band straight back stiff leg deadlift','glutes',array['hamstrings','lower back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de la parte superior de las piernas.','Sujeta la banda con ambas manos frente a los muslos, con las palmas mirando hacia el cuerpo.','Manteniendo la espalda recta y las rodillas ligeramente flexionadas, flexiona las caderas y baja la banda hacia el suelo.','Siente el estiramiento en los isquiotibiales mientras bajas la banda.','Activa los glúteos y los isquiotibiales para levantar el cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1023','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1023-lHeUULr.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1023-lHeUULr.jpg','band',now(),now()),
('band straight leg deadlift','spine',array['hamstrings','glutes']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de los pies.','Sujeta la banda con ambas manos, con las palmas mirando hacia el cuerpo, y mantén los brazos rectos.','Activa el core y mantén una ligera flexión en las rodillas.','Inclínate lentamente hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado.','Baja la banda hacia el suelo manteniendo las piernas rectas.','Haz una pausa breve en la posición baja y luego contrae los glúteos y los isquiotibiales para volver a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1010','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1010-KUaoUV8.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1010-KUaoUV8.jpg','band',now(),now()),
('band twisting overhead press','delts',array['triceps','upper back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.','Sujeta las asas de la banda a la altura de los hombros con las palmas mirando hacia delante.','Activa el core y empuja la banda por encima de la cabeza, extendiendo completamente los brazos.','Mientras empujas, gira el torso hacia un lado, manteniendo las caderas estables.','Haz una pausa breve en la parte alta y luego vuelve a la posición inicial.','Repite el empuje y el giro hacia el lado opuesto.','Continúa alternando lados durante el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1012','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1012-u4bAmKp.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1012-u4bAmKp.jpg','band',now(),now()),
('band two legs calf raise - (band under both legs) v. 2','calves',array['ankles','feet']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y coloca una banda elástica bajo ambos pies.','Sujeta los extremos de la banda con las manos para mantener el equilibrio.','Levanta los talones del suelo lo más alto posible, usando las pantorrillas.','Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1369','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1369-jl6uxZV.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1369-jl6uxZV.jpg','band',now(),now()),
('band underhand pulldown','lats',array['biceps','forearms']::text[],'beginner','compound',array['Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente.','Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.','Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.','Extiende completamente los brazos por encima de la cabeza, manteniendo los codos ligeramente flexionados.','Activa los dorsales y tira de la banda hacia abajo en dirección al pecho, juntando los omóplatos.','Haz una pausa breve en la parte baja del movimiento, luego libera lentamente la tensión y vuelve a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1013','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1013-k6tUeqS.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1013-k6tUeqS.jpg','band',now(),now()),
('band v-up','abs',array['hip flexors']::text[],'beginner','isolation',array['Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.','Activando el abdomen, levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies.','Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1014','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1014-H6ETwO9.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1014-H6ETwO9.jpg','band',now(),now()),
('band vertical pallof press','abs',array['obliques','glutes']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y enrolla la banda alrededor de un objeto firme a la altura del pecho.','Sujeta la banda con ambas manos y aléjate del punto de anclaje, creando tensión en la banda.','Colócate perpendicular al punto de anclaje, con el costado mirando hacia la banda.','Extiende los brazos rectos hacia delante, manteniendo las manos a la altura del pecho.','Activa el core y empuja la banda alejándola del pecho, extendiendo completamente los brazos.','Mantén la posición durante unos segundos y luego lleva lentamente la banda de vuelta hacia el pecho.','Repite el número de repeticiones deseado, luego cambia de lado.']::text[],'Equipo: Banda elástica',true,'1015','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1015-G7PXMlT.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1015-G7PXMlT.jpg','band',now(),now()),
('band wrist curl','forearms',array['biceps','triceps']::text[],'beginner','compound',array['Siéntate en un banco o silla con los pies apoyados en el suelo.','Sujeta la banda con ambas manos, con las palmas hacia arriba, y apoya los antebrazos sobre los muslos.','Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos.','Haz una pausa por un momento en la parte superior, luego baja lentamente las muñecas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1016','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1016-vUTfFHw.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1016-vUTfFHw.jpg','band',now(),now()),
('band y-raise','delts',array['traps','rhomboids']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta la banda frente a los muslos con las palmas mirando hacia adentro.','Mantén los brazos rectos y levántalos hacia arriba y hacia los lados, formando una ''Y'' con el cuerpo.','Junta los omóplatos en la parte superior del movimiento.','Baja lentamente los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Banda elástica',true,'1017','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1017-aHDy5O5.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1017-aHDy5O5.jpg','band',now(),now()),
('barbell alternate biceps curl','biceps',array['forearms']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra en cada mano, con las palmas mirando hacia delante.','Mantén los brazos superiores fijos y exhala mientras levantas el peso contrayendo los bíceps.','Continúa levantando las barras hasta que los bíceps estén completamente contraídos y las barras estén a la altura de los hombros.','Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.','Inhala mientras comienzas a bajar lentamente las barras de vuelta a la posición inicial.','Repite el número de repeticiones deseado, alternando los brazos.']::text[],'Equipo: Barra',true,'0023','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0023-Yza7XrQ.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0023-Yza7XrQ.jpg','barbell',now(),now()),
('barbell bench front squat','quads',array['hamstrings','glutes','calves']::text[],'beginner','compound',array['Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, justo debajo de la clavícula.','Sujeta la barra con un agarre pronado, manteniendo los codos elevados y los brazos superiores paralelos al suelo.','Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado.','Haz una pausa breve en la parte baja de la sentadilla y luego empuja con los talones para volver a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0024','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0024-Y7YcmIJ.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0024-Y7YcmIJ.jpg','barbell',now(),now()),
('barbell bench press','pectorals',array['triceps','shoulders']::text[],'beginner','compound',array['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.','Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.','Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.','Baja la barra lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.','Haz una pausa breve cuando la barra toque el pecho.','Empuja la barra de vuelta a la posición inicial extendiendo los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0025','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0025-EIeI8Vf.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0025-EIeI8Vf.jpg','barbell',now(),now()),
('barbell bench squat','quads',array['glutes','hamstrings','calves']::text[],'beginner','compound',array['Coloca una barra en un soporte de sentadillas a la altura del pecho.','Ponte de pie de espaldas al soporte, con los pies separados a la altura de los hombros.','Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.','Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.','Levanta la barra del soporte y retrocede un paso, asegurándote de que los pies sigan separados a la altura de los hombros.','Baja el cuerpo hacia una sentadilla, manteniendo las rodillas alineadas con los dedos de los pies.','Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0026','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0026-W9pFVv1.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0026-W9pFVv1.jpg','barbell',now(),now()),
('barbell bent arm pullover','lats',array['triceps','chest']::text[],'beginner','compound',array['Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.','Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho.','Baja la barra detrás de la cabeza manteniendo los brazos ligeramente flexionados.','Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1316','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1316-cA9FuWG.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1316-cA9FuWG.jpg','barbell',now(),now()),
('barbell bent over row','upper back',array['biceps','forearms']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.','Inclínate hacia delante desde las caderas manteniendo la espalda recta y el pecho elevado.','Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.','Tira de la barra hacia la parte inferior del pecho retrayendo los omóplatos y contrayendo los músculos de la espalda.','Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0027','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0027-eZyBC3j.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0027-eZyBC3j.jpg','barbell',now(),now()),
('barbell biceps curl (with arm blaster)','biceps',array['forearms']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.','Coloca los brazos superiores contra el soporte para brazos, manteniendo los codos cerca del torso.','Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.','Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.','Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.','Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'2407','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2407-aee2Fcj.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2407-aee2Fcj.jpg','barbell',now(),now()),
('barbell clean and press','quads',array['hamstrings','glutes','shoulders','triceps']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti.','Flexiona las rodillas y las caderas para bajar y agarrar la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.','Empuja con los talones y extiende las caderas y las rodillas para levantar la barra del suelo, manteniéndola cerca del cuerpo.','Cuando la barra llegue a los muslos, extiende las caderas de forma explosiva, encoge los hombros y tira de la barra hacia el pecho.','Cuando la barra llegue a la altura del pecho, baja rápidamente debajo de ella y atrápala a la altura de los hombros, con los codos apuntando hacia delante y las palmas hacia arriba.','Desde la posición de recepción, empuja la barra por encima de la cabeza extendiendo los brazos y llevando la barra recta hacia arriba.','Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0028','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0028-SGY8Zui.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0028-SGY8Zui.jpg','barbell',now(),now()),
('barbell clean-grip front squat','glutes',array['quadriceps','hamstrings','calves','core']::text[],'beginner','compound',array['Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, con los codos apuntando hacia delante.','Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás, como si te sentaras en una silla.','Mantén el pecho elevado y la espalda recta mientras bajas, asegurándote de que las rodillas no sobrepasen los dedos de los pies.','Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.','Haz una pausa breve en la parte baja y luego empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0029','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0029-qi996YS.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0029-qi996YS.jpg','barbell',now(),now()),
('barbell close-grip bench press','triceps',array['chest','shoulders']::text[],'beginner','compound',array['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.','Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.','Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.','Haz una pausa breve cuando la barra toque el pecho.','Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0030','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0030-J6Dx1Mu.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0030-J6Dx1Mu.jpg','barbell',now(),now()),
('barbell curl','biceps',array['forearms']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas mirando hacia delante.','Mantén los codos cerca del torso y exhala mientras levantas el peso contrayendo los bíceps.','Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.','Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.','Inhala mientras comienzas a bajar lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0031','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0031-25GPyDY.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0031-25GPyDY.jpg','barbell',now(),now()),
('barbell deadlift','glutes',array['hamstrings','lower back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti.','Flexiona las rodillas y las caderas para bajar el torso y agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.','Mantén la espalda recta y el pecho elevado mientras empujas con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas.','Al ponerte de pie, aprieta los glúteos y mantén el core activado.','Baja la barra de vuelta al suelo flexionando las caderas y las rodillas, manteniendo la espalda recta.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0032','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0032-ila4NZS.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0032-ila4NZS.jpg','barbell',now(),now()),
('barbell decline bench press','pectorals',array['triceps','shoulders']::text[],'beginner','compound',array['Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.','Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.','Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.','Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0033','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0033-GrO65fd.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0033-GrO65fd.jpg','barbell',now(),now()),
('barbell decline bent arm pullover','lats',array['triceps','chest']::text[],'beginner','compound',array['Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.','Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho.','Baja la barra detrás de la cabeza de forma controlada, manteniendo los brazos ligeramente flexionados.','Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial contrayendo los dorsales.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0034','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0034-hMEptv0.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0034-hMEptv0.jpg','barbell',now(),now()),
('barbell decline close grip to skull press','triceps',array['chest','shoulders']::text[],'beginner','compound',array['Túmbate en un banco declinado con la cabeza más baja que los pies y sujeta una barra con un agarre cerrado.','Baja la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos.','Haz una pausa breve y luego extiende los brazos para empujar la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0035','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0035-LMGXZn8.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0035-LMGXZn8.jpg','barbell',now(),now()),
('barbell decline pullover','pectorals',array['triceps','shoulders']::text[],'beginner','compound',array['Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.','Sujeta la barra con un agarre pronado (palmas mirando hacia afuera) y las manos un poco más separadas que el ancho de los hombros.','Extiende los brazos por encima del pecho, manteniendo una ligera flexión en los codos.','Baja la barra describiendo un arco detrás de la cabeza, sintiendo un estiramiento en el pecho y los hombros.','Haz una pausa breve y luego devuelve la barra a la posición inicial invirtiendo el movimiento.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1255','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1255-9sgNE2O.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1255-9sgNE2O.jpg','barbell',now(),now()),
('barbell decline wide-grip press','pectorals',array['triceps','shoulders']::text[],'beginner','compound',array['Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.','Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.','Baja la barra hacia el pecho, manteniendo los codos hacia los lados.','Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0036','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0036-hl8DUh8.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0036-hl8DUh8.jpg','barbell',now(),now()),
('barbell decline wide-grip pullover','lats',array['triceps','chest']::text[],'beginner','compound',array['Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.','Sujeta una barra con un agarre amplio y extiende los brazos rectos por encima del pecho.','Baja la barra detrás de la cabeza de forma controlada, manteniendo los brazos rectos.','Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0037','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0037-Hj4FOCd.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0037-Hj4FOCd.jpg','barbell',now(),now()),
('barbell drag curl','biceps',array['forearms']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.','Deja que la barra cuelgue a la longitud del brazo frente a los muslos.','Manteniendo los brazos superiores fijos, levanta la barra hacia el pecho contrayendo los bíceps.','Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0038','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0038-IENzBdA.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0038-IENzBdA.jpg','barbell',now(),now()),
('barbell floor calf raise','calves',array['hamstrings']::text[],'beginner','isolation',array['Coloca una barra en el suelo frente a ti.','Ponte de pie con la parte delantera de los pies sobre el borde de la barra, dejando los talones colgando.','Sujétate de un objeto estable para mantener el equilibrio si es necesario.','Levanta los talones lo más alto posible, usando las pantorrillas para elevar el cuerpo.','Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1370','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1370-2IHEa2T.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1370-2IHEa2T.jpg','barbell',now(),now()),
('barbell front chest squat','glutes',array['quadriceps','hamstrings','calves','core']::text[],'beginner','compound',array['Empieza de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.','Sujeta la barra frente al pecho con las manos separadas a la altura de los hombros, los codos apuntando hacia delante.','Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.','Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.','Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0039','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0039-IeTIEqg.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0039-IeTIEqg.jpg','barbell',now(),now()),
('barbell front raise','delts',array['biceps','triceps']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado.','Mantén los brazos rectos y levanta la barra hacia delante y hacia arriba hasta que alcance la altura de los hombros.','Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0041','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0041-b2Uoz54.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0041-b2Uoz54.jpg','barbell',now(),now()),
('barbell front raise and pullover','pectorals',array['deltoids','triceps']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.','Mantén los brazos rectos y levanta la barra frente a ti hasta que alcance la altura de los hombros.','Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.','A continuación, baja la barra detrás de la cabeza, manteniendo los brazos rectos.','Haz una pausa breve en la parte baja y luego levanta la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0040','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0040-33AzZeV.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0040-33AzZeV.jpg','barbell',now(),now()),
('barbell front squat','glutes',array['quadriceps','hamstrings','calves','core']::text[],'beginner','compound',array['Empieza de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.','Sujeta la barra frente a los hombros, apoyándola sobre la clavícula y los hombros.','Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.','Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.','Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0042','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0042-zG0zs85.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0042-zG0zs85.jpg','barbell',now(),now()),
('barbell full squat','glutes',array['quadriceps','hamstrings','calves','core']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.','Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.','Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo.','Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla.','Baja hasta que los muslos queden paralelos al suelo o un poco por debajo.','Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.','Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0043','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0043-qXTaZnJ.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0043-qXTaZnJ.jpg','barbell',now(),now()),
('barbell full squat (back pov)','glutes',array['quadriceps','hamstrings','calves','core']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.','Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.','Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo.','Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla.','Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.','Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.','Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1461','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1461-DhMl549.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1461-DhMl549.jpg','barbell',now(),now()),
('barbell full squat (side pov)','glutes',array['quadriceps','hamstrings','calves','core']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.','Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.','Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo.','Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla.','Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.','Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.','Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1462','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1462-iYzB0Cz.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1462-iYzB0Cz.jpg','barbell',now(),now()),
('barbell full zercher squat','glutes',array['quadriceps','hamstrings','calves','core']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.','Sujeta la barra en el pliegue de los codos, agarrándola con las manos para mantener la estabilidad.','Activa el core y mantén el pecho elevado mientras bajas las caderas hacia atrás y hacia abajo en una posición de sentadilla.','Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.','Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.','Empuja con los talones para volver a ponerte de pie, apretando los glúteos en la parte alta del movimiento.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1545','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1545-vR1vold.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1545-vR1vold.jpg','barbell',now(),now()),
('barbell glute bridge','glutes',array['hamstrings','lower back']::text[],'beginner','compound',array['Empieza tumbado boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.','Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos.','Activa los glúteos y el core, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.','Haz una pausa breve en la parte alta, apretando los glúteos.','Baja lentamente las caderas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1409','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1409-qKBpF7I.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1409-qKBpF7I.jpg','barbell',now(),now()),
('barbell glute bridge two legs on bench (male)','glutes',array['hamstrings','core']::text[],'beginner','compound',array['Empieza sentado en el borde de un banco con la parte superior de la espalda apoyada contra él y los pies planos sobre el suelo, separados a la altura de las caderas.','Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos.','Activa los glúteos y el core, luego empuja con los talones para levantar las caderas del banco, creando una línea recta desde las rodillas hasta los hombros.','Haz una pausa breve en la parte alta, apretando los glúteos.','Baja lentamente las caderas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'3562','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3562-qg2PGl6.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3562-qg2PGl6.jpg','barbell',now(),now()),
('barbell good morning','hamstrings',array['lower back']::text[],'beginner','isolation',array['Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada sobre la parte superior de la espalda.','Manteniendo la espalda recta y el core activado, flexiona las caderas hacia delante, empujando los glúteos hacia atrás como si intentaras tocar la pared detrás de ti con ellos.','Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.','Haz una pausa breve y luego vuelve a la posición inicial apretando los glúteos y empujando las caderas hacia delante.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0044','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0044-XlZ4lAC.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0044-XlZ4lAC.jpg','barbell',now(),now()),
('barbell guillotine bench press','pectorals',array['shoulders','triceps']::text[],'beginner','compound',array['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.','Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.','Baja la barra lentamente hacia el cuello, manteniendo los codos apuntando hacia afuera.','Haz una pausa breve cuando la barra esté justo encima del cuello.','Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0045','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0045-GXoaSgn.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0045-GXoaSgn.jpg','barbell',now(),now()),
('barbell hack squat','glutes',array['quadriceps','hamstrings','calves']::text[],'beginner','compound',array['Empieza de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.','Sujeta la barra detrás de las piernas, apoyándola en la parte superior de los muslos.','Baja el cuerpo flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado.','Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.','Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0046','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0046-5VCj6iH.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0046-5VCj6iH.jpg','barbell',now(),now()),
('barbell high bar squat','glutes',array['quadriceps','hamstrings','calves','core']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.','Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios.','Activa el core y mantén el pecho elevado mientras comienzas a bajar en sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.','Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.','Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1436','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1436-Gnfo4FM.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1436-Gnfo4FM.jpg','barbell',now(),now()),
('barbell incline bench press','pectorals',array['shoulders','triceps']::text[],'beginner','compound',array['Coloca un banco inclinado a un ángulo de 45 grados.','Túmbate en el banco con los pies planos sobre el suelo.','Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.','Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos a un ángulo de 45 grados.','Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0047','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0047-3TZduzM.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0047-3TZduzM.jpg','barbell',now(),now()),
('barbell incline close grip bench press','triceps',array['chest','shoulders']::text[],'beginner','compound',array['Coloca un banco inclinado a un ángulo de 45 grados.','Túmbate en el banco con los pies planos sobre el suelo.','Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.','Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.','Haz una pausa breve cuando la barra toque el pecho.','Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1719','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1719-gx7s7uF.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1719-gx7s7uF.jpg','barbell',now(),now()),
('barbell incline reverse-grip press','triceps',array['chest','shoulders']::text[],'beginner','compound',array['Coloca un banco inclinado a un ángulo de 45 grados.','Recuéstate en el banco y agarra la barra con un agarre invertido, con las manos un poco más separadas que el ancho de los hombros.','Saca la barra del soporte y bájala hacia la parte superior del pecho, manteniendo los codos pegados al cuerpo.','Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0048','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0048-641mIfk.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0048-641mIfk.jpg','barbell',now(),now()),
('barbell incline row','upper back',array['biceps','forearms']::text[],'beginner','compound',array['Coloca un banco inclinado a un ángulo de 45 grados.','Túmbate boca abajo en el banco con el pecho apoyado en el respaldo y los pies planos sobre el suelo.','Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.','Mantén la espalda recta y el core activado.','Tira de la barra hacia el pecho, juntando los omóplatos.','Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0049','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0049-dmgMp3n.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0049-dmgMp3n.jpg','barbell',now(),now()),
('barbell incline shoulder raise','serratus anterior',array['deltoids','trapezius']::text[],'beginner','compound',array['Coloca un banco inclinado a un ángulo de 45 grados.','Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.','Sujeta una barra con un agarre pronado, un poco más ancho que la separación de los hombros.','Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.','Levanta lentamente la barra por encima de la cabeza, extendiendo completamente los brazos.','Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la altura de los hombros.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0050','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0050-xi0yckC.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0050-xi0yckC.jpg','barbell',now(),now()),
('barbell jefferson squat','glutes',array['quadriceps','hamstrings','calves']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.','Sujeta la barra con un agarre pronado, apoyándola en la parte delantera del cuerpo, justo debajo de la cintura.','Da un paso con el pie izquierdo hacia delante y el pie derecho hacia atrás, manteniendo los pies separados a la altura de los hombros.','Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.','Empuja con los talones para volver a ponerte de pie en la posición inicial.','Repite el movimiento, alternando el pie delantero y el trasero en cada repetición.']::text[],'Equipo: Barra',true,'0051','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0051-pkSoCW9.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0051-pkSoCW9.jpg','barbell',now(),now()),
('barbell jm bench press','triceps',array['chest','shoulders']::text[],'beginner','compound',array['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.','Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.','Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.','Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0052','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0052-ZsiqXYa.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0052-ZsiqXYa.jpg','barbell',now(),now()),
('barbell jump squat','glutes',array['quadriceps','hamstrings','calves']::text[],'beginner','compound',array['Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.','Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.','Al llegar a la parte baja de la sentadilla, impúlsate hacia arriba saltando desde el suelo.','Al saltar, extiende las caderas, las rodillas y los tobillos, empujando con la punta de los pies.','Aterriza con suavidad de vuelta en la posición de sentadilla y repite el movimiento de inmediato el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0053','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0053-1gFNTZV.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0053-1gFNTZV.jpg','barbell',now(),now()),
('barbell lateral lunge','glutes',array['quadriceps','hamstrings','calves']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.','Da un paso grande hacia el lado con el pie derecho, manteniendo el pie izquierdo fijo en el suelo.','Flexiona la rodilla derecha y baja el cuerpo hacia una posición de zancada, manteniendo la pierna izquierda recta.','Empuja con el pie derecho y vuelve a la posición inicial.','Repite hacia el otro lado, dando el paso con el pie izquierdo.']::text[],'Equipo: Barra',true,'1410','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1410-py1HSzx.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1410-py1HSzx.jpg','barbell',now(),now()),
('barbell low bar squat','glutes',array['quadriceps','hamstrings','calves']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y la barra apoyada sobre la parte superior de la espalda.','Manteniendo el pecho elevado y el core activado, baja lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás.','Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.','Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1435','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1435-bTpEUcm.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1435-bTpEUcm.jpg','barbell',now(),now()),
('barbell lunge','glutes',array['quadriceps','hamstrings','calves']::text[],'beginner','compound',array['Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda.','Da un paso hacia delante con el pie derecho, manteniendo el torso erguido.','Baja el cuerpo flexionando la rodilla derecha hasta que el muslo quede paralelo al suelo.','Empuja con el talón derecho para regresar a la posición inicial.','Repite con la pierna izquierda, alternando las piernas el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0054','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0054-t8iSghb.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0054-t8iSghb.jpg','barbell',now(),now()),
('barbell lying back of the head tricep extension','triceps',array['shoulders']::text[],'beginner','isolation',array['Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.','Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.','Manteniendo los brazos superiores fijos, baja lentamente la barra detrás de la cabeza flexionando los codos.','Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1720','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1720-yg8Totb.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1720-yg8Totb.jpg','barbell',now(),now()),
('barbell lying close-grip press','triceps',array['chest','shoulders']::text[],'beginner','compound',array['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.','Agarra la barra con un agarre cerrado, manos separadas a la altura de los hombros, con las palmas mirando hacia los pies.','Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.','Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.','Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0055','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0055-EcaV7aL.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0055-EcaV7aL.jpg','barbell',now(),now()),
('barbell lying close-grip triceps extension','triceps',array['shoulders']::text[],'beginner','isolation',array['Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.','Agarra la barra con un agarre cerrado, manos separadas a la altura de los hombros, con las palmas hacia arriba.','Extiende completamente los brazos, levantando la barra por encima del pecho.','Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.','Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0056','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0056-HJ63mSO.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0056-HJ63mSO.jpg','barbell',now(),now()),
('barbell lying extension','triceps',array['shoulders']::text[],'beginner','isolation',array['Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.','Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.','Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.','Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0057','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0057-EMpUwRI.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0057-EMpUwRI.jpg','barbell',now(),now()),
('barbell lying lifting (on hip)','glutes',array['hamstrings','quadriceps']::text[],'beginner','compound',array['Túmbate boca arriba en un banco con los pies planos sobre el suelo y las rodillas flexionadas.','Sujeta la barra con un agarre pronado y colócala sobre las caderas.','Activando los glúteos, levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.','Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0058','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0058-SNFfUff.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0058-SNFfUff.jpg','barbell',now(),now()),
('barbell lying preacher curl','biceps',array['forearms']::text[],'beginner','isolation',array['Siéntate en un banco predicador con el pecho apoyado en el respaldo y los brazos extendidos sobre el borde, sujetando una barra con un agarre supino.','Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.','Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.','Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.','Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0059','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0059-SYJ4Bkt.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0059-SYJ4Bkt.jpg','barbell',now(),now()),
('barbell lying triceps extension','triceps',array['shoulders']::text[],'beginner','isolation',array['Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.','Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.','Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.','Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0061','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0061-iZop9xO.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0061-iZop9xO.jpg','barbell',now(),now()),
('barbell lying triceps extension skull crusher','triceps',array['shoulders']::text[],'beginner','isolation',array['Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.','Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.','Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.','Haz una pausa breve cuando la barra esté justo encima de la frente y luego extiende los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0060','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0060-h8LFzo9.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0060-h8LFzo9.jpg','barbell',now(),now()),
('barbell narrow stance squat','glutes',array['quadriceps','hamstrings','calves']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.','Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.','Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás.','Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.','Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0063','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0063-elhhVgj.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0063-elhhVgj.jpg','barbell',now(),now()),
('barbell one arm bent over row','upper back',array['biceps','forearms']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una barra con una mano usando un agarre pronado.','Inclínate hacia delante desde las caderas, manteniendo la espalda recta y la cabeza en posición neutral.','Tira de la barra hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.','Baja la barra de vuelta a la posición inicial de forma controlada.','Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[],'Equipo: Barra',true,'0064','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0064-Jsgsc27.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0064-Jsgsc27.jpg','barbell',now(),now()),
('barbell one arm floor press','triceps',array['chest','shoulders']::text[],'beginner','compound',array['Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.','Sujeta la barra con una mano, con la palma hacia arriba, y extiende el brazo recto por encima del pecho.','Baja la barra lentamente hacia el pecho, manteniendo el codo cerca del cuerpo.','Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de brazo.']::text[],'Equipo: Barra',true,'0065','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0065-vtusOWT.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0065-vtusOWT.jpg','barbell',now(),now()),
('barbell one arm side deadlift','glutes',array['hamstrings','quadriceps','lower back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra en una mano con un agarre pronado.','Mantén la espalda recta y el core activado.','Flexiona las caderas y baja la barra hacia el exterior de la pierna, manteniendo el brazo recto y el pecho elevado.','Baja la barra tanto como puedas manteniendo una buena forma.','Haz una pausa por un momento, luego regresa lentamente a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de lado.']::text[],'Equipo: Barra',true,'0066','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0066-2DxtqHL.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0066-2DxtqHL.jpg','barbell',now(),now()),
('barbell one arm snatch','delts',array['traps','forearms','core']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.','Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.','Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.','Extiende las caderas, las rodillas y los tobillos de forma explosiva, impulsando la barra hacia arriba.','Cuando la barra llegue a la altura del pecho, tira de ella hacia arriba con el brazo, manteniéndola cerca del cuerpo.','Rota el codo por debajo de la barra y extiende el brazo completamente por encima de la cabeza, bloqueando el codo.','Baja la barra de vuelta a la posición inicial de forma controlada.','Repite el número de repeticiones deseado, luego cambia de brazo.']::text[],'Equipo: Barra',true,'0067','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0067-xHKN2s8.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0067-xHKN2s8.jpg','barbell',now(),now()),
('barbell one leg squat','quads',array['glutes','hamstrings','calves']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda.','Levanta un pie del suelo y extiéndelo hacia delante, manteniéndolo paralelo al suelo.','Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla, manteniendo el pecho elevado y la espalda recta.','Baja hasta que el muslo quede paralelo al suelo, luego empuja con el talón para volver a la posición inicial.','Repite el número de repeticiones deseado y luego cambia de pierna y repite.']::text[],'Equipo: Barra',true,'0068','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0068-uKyN64F.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0068-uKyN64F.jpg','barbell',now(),now()),
('barbell overhead squat','quads',array['glutes','hamstrings','calves','core']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.','Sujeta la barra con un agarre amplio, colocándola por encima de la cabeza con los brazos completamente extendidos.','Activa el core y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con los dedos de los pies.','Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0069','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0069-gfk9kD4.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0069-gfk9kD4.jpg','barbell',now(),now()),
('barbell palms down wrist curl over a bench','forearms',array['biceps','brachialis']::text[],'beginner','compound',array['Siéntate en un banco con los pies planos sobre el suelo y los antebrazos apoyados sobre los muslos, con las palmas hacia abajo.','Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros.','Baja la barra hacia el suelo flexionando las muñecas, manteniendo los antebrazos fijos.','Haz una pausa breve en la parte baja y luego levanta lentamente la barra extendiendo las muñecas.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1411','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1411-yzYH9pI.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1411-yzYH9pI.jpg','barbell',now(),now()),
('barbell palms up wrist curl over a bench','forearms',array['biceps','shoulders']::text[],'beginner','compound',array['Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba.','Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde.','Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.','Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1412','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1412-SJAA2IQ.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1412-SJAA2IQ.jpg','barbell',now(),now()),
('barbell pendlay row','upper back',array['biceps','forearms']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.','Inclínate hacia delante desde las caderas manteniendo la espalda recta y el pecho elevado.','Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.','Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos.','Baja la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'3017','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3017-r0z6xzQ.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3017-r0z6xzQ.jpg','barbell',now(),now()),
('barbell pin presses','triceps',array['shoulders']::text[],'beginner','isolation',array['Coloca una barra en un rack de potencia a la altura del pecho.','Ponte de pie frente a la barra y colócate debajo de ella, con los pies separados a la altura de los hombros.','Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.','Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.','Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.','Haz una pausa breve cuando la barra toque el pecho.','Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1751','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1751-bndCa3Q.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1751-bndCa3Q.jpg','barbell',now(),now()),
('barbell preacher curl','biceps',array['forearms']::text[],'beginner','isolation',array['Siéntate en un banco predicador con los brazos superiores apoyados en el cojín y el pecho contra el soporte.','Agarra la barra con un agarre supino, un poco más ancho que la separación de los hombros.','Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros.','Haz una pausa breve en la parte alta, apretando los bíceps.','Inhala y baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0070','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0070-qOgPVf6.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0070-qOgPVf6.jpg','barbell',now(),now()),
('barbell press sit-up','abs',array['shoulders','chest']::text[],'beginner','compound',array['Túmbate boca arriba en una esterilla con las rodillas flexionadas y los pies planos sobre el suelo.','Sujeta la barra con un agarre pronado, apoyándola sobre el pecho.','Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.','Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0071','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0071-wnEscH8.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0071-wnEscH8.jpg','barbell',now(),now()),
('barbell prone incline curl','biceps',array['forearms']::text[],'beginner','isolation',array['Coloca un banco inclinado a un ángulo de 45 grados.','Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él.','Sujeta una barra con un agarre supino, separado a la altura de los hombros.','Extiende completamente los brazos, dejando que la barra cuelgue hacia el suelo.','Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.','Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.','Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.','Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0072','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0072-WLvTAv5.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0072-WLvTAv5.jpg','barbell',now(),now()),
('barbell pullover','lats',array['chest','triceps']::text[],'beginner','compound',array['Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.','Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho.','Manteniendo los brazos rectos, baja la barra detrás de la cabeza de forma controlada hasta sentir un estiramiento en los dorsales.','Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0073','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0073-i6LWjok.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0073-i6LWjok.jpg','barbell',now(),now()),
('barbell pullover to press','lats',array['triceps','chest','shoulders']::text[],'beginner','compound',array['Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.','Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho.','Manteniendo los brazos rectos, baja la barra detrás de la cabeza con un movimiento en forma de arco hasta sentir un estiramiento en los dorsales.','Haz una pausa breve, luego invierte el movimiento y empuja la barra de vuelta a la posición inicial por encima del pecho.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0022','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0022-znLogoF.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0022-znLogoF.jpg','barbell',now(),now()),
('barbell rack pull','glutes',array['hamstrings','lower back']::text[],'beginner','compound',array['Coloca una barra en un soporte a la altura de la rodilla.','Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.','Flexiona las caderas y las rodillas para bajar y agarrar la barra con un agarre pronado, manos separadas a la altura de los hombros.','Activa el core y levanta la barra extendiendo las caderas y las rodillas, llevando los hombros hacia atrás y apretando los glúteos en la parte alta.','Baja la barra de vuelta a la posición inicial flexionando las caderas y las rodillas.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0074','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0074-za9Ni4z.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0074-za9Ni4z.jpg','barbell',now(),now()),
('barbell rear delt raise','delts',array['traps','rhomboids']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.','Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.','Levanta la barra hacia los lados, manteniendo los brazos rectos, hasta que queden paralelos al suelo.','Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0075','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0075-Ln9iTbU.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0075-Ln9iTbU.jpg','barbell',now(),now()),
('barbell rear delt row','delts',array['trapezius','rhomboids','biceps']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.','Sujeta una barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.','Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado.','Tira de la barra hacia el pecho, juntando los omóplatos.','Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0076','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0076-S9zHIvU.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0076-S9zHIvU.jpg','barbell',now(),now()),
('barbell rear lunge','glutes',array['quadriceps','hamstrings','calves']::text[],'beginner','compound',array['Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda.','Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie.','Flexiona ambas rodillas para bajar el cuerpo hasta que el muslo izquierdo quede paralelo al suelo.','Empuja con el talón izquierdo para volver a la posición inicial.','Repite con la otra pierna.']::text[],'Equipo: Barra',true,'0078','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0078-VaP75jl.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0078-VaP75jl.jpg','barbell',now(),now()),
('barbell rear lunge v. 2','glutes',array['quadriceps','hamstrings','calves']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda.','Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie.','Flexiona ambas rodillas para bajar el cuerpo hasta que el muslo izquierdo quede paralelo al suelo.','Empuja con el talón izquierdo para volver a la posición inicial.','Repite con la otra pierna.']::text[],'Equipo: Barra',true,'0077','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0077-62Nw60O.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0077-62Nw60O.jpg','barbell',now(),now()),
('barbell revers wrist curl v. 2','forearms',array['biceps','brachialis']::text[],'beginner','compound',array['Siéntate en un banco con los pies planos sobre el suelo y las rodillas flexionadas.','Sujeta una barra con un agarre pronado, palmas hacia abajo, y las manos separadas a la altura de los hombros.','Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.','Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.','Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0079','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0079-qDnGfDb.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0079-qDnGfDb.jpg','barbell',now(),now()),
('barbell reverse close-grip bench press','triceps',array['chest','shoulders']::text[],'beginner','compound',array['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.','Agarra la barra con un agarre invertido, manos separadas a la altura de los hombros.','Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.','Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.','Haz una pausa breve cuando la barra esté justo encima del pecho.','Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'2187','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2187-YqJw82s.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2187-YqJw82s.jpg','barbell',now(),now()),
('barbell reverse curl','biceps',array['forearms']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.','Mantén los brazos superiores fijos y exhala mientras levantas la barra hacia arriba, contrayendo los bíceps.','Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.','Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.','Inhala mientras bajas lentamente la barra de vuelta a la posición inicial, manteniendo los brazos superiores fijos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0080','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0080-xNrS20v.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0080-xNrS20v.jpg','barbell',now(),now()),
('barbell reverse grip bent over row','upper back',array['biceps','forearms']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.','Sujeta una barra con un agarre pronado, palmas hacia abajo, y las manos un poco más separadas que el ancho de los hombros.','Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo.','Tira de la barra hacia la parte inferior del pecho, juntando los omóplatos.','Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0118','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0118-SzX3uzM.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0118-SzX3uzM.jpg','barbell',now(),now()),
('barbell reverse grip decline bench press','pectorals',array['triceps','shoulders']::text[],'beginner','compound',array['Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.','Agarra la barra con un agarre invertido, un poco más ancho que la separación de los hombros.','Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.','Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1256','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1256-DotAgEF.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1256-DotAgEF.jpg','barbell',now(),now()),
('barbell reverse grip incline bench press','pectorals',array['triceps','shoulders']::text[],'beginner','compound',array['Coloca un banco inclinado a un ángulo de 45 grados.','Túmbate en el banco con los pies planos sobre el suelo.','Agarra la barra con un agarre invertido, manos un poco más separadas que el ancho de los hombros.','Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.','Haz una pausa breve cuando la barra toque el pecho.','Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1257','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1257-DU7I633.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1257-DU7I633.jpg','barbell',now(),now()),
('barbell reverse grip incline bench row','upper back',array['biceps','forearms']::text[],'beginner','compound',array['Coloca un banco inclinado a un ángulo de 45 grados.','Siéntate en el banco frente al respaldo con el pecho apoyado contra él.','Sujeta la barra con un agarre invertido (palmas hacia abajo) y las manos un poco más separadas que el ancho de los hombros.','Mantén la espalda recta y el core activado.','Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos.','Haz una pausa breve en la parte alta del movimiento.','Baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1317','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1317-8d8qJQI.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1317-8d8qJQI.jpg','barbell',now(),now()),
('barbell reverse grip skullcrusher','triceps',array['forearms']::text[],'beginner','isolation',array['Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.','Sujeta la barra con un agarre invertido, palmas mirando hacia la cara, y las manos separadas a la altura de los hombros.','Extiende los brazos rectos por encima del pecho, manteniendo los codos hacia dentro y las muñecas rectas.','Baja lentamente la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos.','Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1721','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1721-yRLPCLu.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1721-yRLPCLu.jpg','barbell',now(),now()),
('barbell reverse preacher curl','biceps',array['forearms']::text[],'beginner','isolation',array['Siéntate en un banco predicador con el pecho apoyado en el cojín y los brazos extendidos rectos hacia abajo, sujetando una barra con un agarre pronado.','Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia arriba mientras contraes los bíceps.','Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.','Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.','Inhala y baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0081','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0081-4LIG9xr.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0081-4LIG9xr.jpg','barbell',now(),now()),
('barbell reverse wrist curl','forearms',array['biceps','brachialis']::text[],'beginner','compound',array['Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre pronado, con las palmas hacia abajo.','Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.','Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia el cuerpo.','Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0082','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0082-LsZkfU6.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0082-LsZkfU6.jpg','barbell',now(),now()),
('barbell rollerout','abs',array['lower back']::text[],'beginner','isolation',array['Ponte de rodillas en el suelo y sujeta una barra con ambas manos, separadas a la altura de los hombros.','Haz rodar la barra hacia delante, extendiendo los brazos y manteniendo el core activado.','Continúa rodando hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza.','Haz una pausa breve y luego haz rodar lentamente la barra de vuelta hacia las rodillas, manteniendo el control.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0084','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0084-7M66AVi.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0084-7M66AVi.jpg','barbell',now(),now()),
('barbell rollerout from bench','abs',array['shoulders','triceps']::text[],'beginner','compound',array['Empieza de rodillas en el suelo con una barra colocada sobre un banco frente a ti.','Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.','Manteniendo el core activado y la espalda recta, haz rodar lentamente la barra hacia delante, extendiendo los brazos frente a ti.','Continúa haciendo rodar la barra hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza.','Haz una pausa breve en la posición de extensión total, luego haz rodar lentamente la barra de vuelta hacia el cuerpo, volviendo a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0083','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0083-Gxg9lDc.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0083-Gxg9lDc.jpg','barbell',now(),now()),
('barbell romanian deadlift','glutes',array['hamstrings','lower back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante.','Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.','Flexiona las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas.','Baja la barra hacia el suelo, manteniéndola cerca del cuerpo.','Siente el estiramiento en los isquiotibiales mientras bajas la barra.','Cuando sientas el estiramiento en los isquiotibiales, empuja las caderas hacia delante y ponte de pie.','Aprieta los glúteos en la parte alta del movimiento.','Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0085','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0085-wQ2c4XD.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0085-wQ2c4XD.jpg','barbell',now(),now()),
('barbell seated behind head military press','delts',array['triceps','upper back']::text[],'beginner','compound',array['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.','Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros.','Levanta la barra del soporte y bájala a la altura de los hombros, detrás de la cabeza.','Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos.','Baja la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0086','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0086-ngPpyRS.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0086-ngPpyRS.jpg','barbell',now(),now()),
('barbell seated bradford rocky press','delts',array['triceps','upper back']::text[],'beginner','compound',array['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.','Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros.','Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y apuntando hacia delante.','Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.','Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0087','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0087-0dCyly0.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0087-0dCyly0.jpg','barbell',now(),now()),
('barbell seated calf raise','calves',array['hamstrings','quadriceps']::text[],'beginner','compound',array['Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre los muslos.','Coloca la parte delantera de los pies sobre una plataforma elevada, como un bloque o un escalón.','Coloca la barra sobre los muslos y sujétala con firmeza con las manos.','Manteniendo la espalda recta y el core activado, levanta los talones del suelo extendiendo los tobillos.','Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0088','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0088-ktsFQAZ.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0088-ktsFQAZ.jpg','barbell',now(),now()),
('barbell seated close grip behind neck triceps extension','triceps',array['shoulders']::text[],'beginner','isolation',array['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.','Sujeta la barra con un agarre cerrado detrás del cuello, con las palmas mirando hacia delante.','Mantén los codos cerca de la cabeza y baja lentamente la barra hacia la parte de atrás de la cabeza.','Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1718','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1718-4CBIBOM.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1718-4CBIBOM.jpg','barbell',now(),now()),
('barbell seated close-grip concentration curl','biceps',array['forearms']::text[],'beginner','isolation',array['Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, manos separadas a la altura de los hombros.','Apoya los brazos superiores contra el interior de los muslos, justo por encima de las rodillas, y deja que la barra cuelgue frente a ti.','Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros, contrayendo los bíceps.','Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0089','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0089-1V1gj1u.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0089-1V1gj1u.jpg','barbell',now(),now()),
('barbell seated good morning','glutes',array['hamstrings','lower back']::text[],'beginner','compound',array['Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre la parte superior de la espalda.','Mantén la espalda recta y el pecho elevado.','Inclínate lentamente hacia delante desde las caderas, bajando el torso hacia el suelo.','Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0090','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0090-d960PgE.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0090-d960PgE.jpg','barbell',now(),now()),
('barbell seated overhead press','delts',array['triceps','upper back']::text[],'beginner','compound',array['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.','Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros.','Levanta la barra del soporte y llévala a la altura de los hombros, con los codos flexionados y las palmas hacia delante.','Empuja la barra por encima de la cabeza extendiendo completamente los brazos.','Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la altura de los hombros.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0091','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0091-kTbSH9h.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0091-kTbSH9h.jpg','barbell',now(),now()),
('barbell seated overhead triceps extension','triceps',array['shoulders']::text[],'beginner','isolation',array['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.','Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y levántala por encima de la cabeza.','Baja la barra detrás de la cabeza flexionando los codos, manteniendo los brazos superiores cerca de la cabeza.','Haz una pausa breve y luego extiende los brazos para levantar la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0092','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0092-5uFK1xr.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0092-5uFK1xr.jpg','barbell',now(),now()),
('barbell seated twist','abs',array['obliques','lower back']::text[],'beginner','compound',array['Siéntate en un banco plano con los pies planos sobre el suelo y las rodillas flexionadas.','Sujeta una barra con ambas manos frente al pecho, manteniendo los codos ligeramente flexionados.','Activa el core y gira lentamente el torso hacia un lado, manteniendo la espalda recta.','Haz una pausa breve al final del giro y luego rota lentamente de vuelta a la posición inicial.','Repite el giro hacia el otro lado.','Continúa alternando lados durante el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0094','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0094-dFSNDOA.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0094-dFSNDOA.jpg','barbell',now(),now()),
('barbell shrug','traps',array['shoulders']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a ti con un agarre pronado.','Mantén los brazos rectos y la espalda recta durante todo el ejercicio.','Levanta los hombros hacia las orejas lo más alto posible, apretando los trapecios en la parte alta.','Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0095','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0095-dG7tG5y.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0095-dG7tG5y.jpg','barbell',now(),now()),
('barbell side bent v. 2','abs',array['obliques','lower back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con ambas manos, con las palmas hacia abajo.','Mantén la espalda recta y el core activado durante todo el ejercicio.','Inclina lentamente el torso hacia el lado derecho, bajando la barra hacia tu rodilla derecha.','Haz una pausa breve y luego vuelve a la posición inicial.','Repite el movimiento hacia el lado izquierdo.','Continúa alternando lados durante el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0096','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0096-i4JkUaL.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0096-i4JkUaL.jpg','barbell',now(),now()),
('barbell side split squat','quads',array['glutes','hamstrings','calves']::text[],'beginner','compound',array['Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.','Sujeta una barra sobre la parte superior de la espalda, apoyándola en los trapecios.','Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, flexionando las rodillas y las caderas.','Al bajar, empuja las rodillas hacia los lados y mantén el peso sobre los talones.','Baja hasta que los muslos queden paralelos al suelo, luego empuja con los talones para volver a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0098','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0098-W31mMjd.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0098-W31mMjd.jpg','barbell',now(),now()),
('barbell side split squat v. 2','quads',array['glutes','hamstrings','calves']::text[],'beginner','compound',array['Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.','Sujeta una barra sobre la parte superior de la espalda, apoyándola en los hombros.','Da un paso grande hacia el lado con el pie derecho, manteniendo el pie izquierdo fijo en el suelo.','Flexiona la rodilla derecha y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y la espalda recta.','Empuja con el talón derecho para regresar a la posición inicial.','Repite hacia el otro lado, dando el paso con el pie izquierdo.','Continúa alternando lados durante el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0097','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0097-HUEqZ1y.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0097-HUEqZ1y.jpg','barbell',now(),now()),
('barbell single leg deadlift','glutes',array['hamstrings','lower back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de las caderas, sujetando una barra frente a los muslos con agarre prono.','Traslada el peso hacia el pie izquierdo y levanta el pie derecho ligeramente del suelo.','Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y la pierna derecha extendida detrás de ti para el equilibrio.','Baja la barra hacia el suelo, manteniéndola cerca del cuerpo y la pierna izquierda ligeramente flexionada.','Haz una pausa breve en la posición más baja, luego activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de lado.']::text[],'Equipo: Barra',true,'1756','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1756-gEyURal.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1756-gEyURal.jpg','barbell',now(),now()),
('barbell single leg split squat','quads',array['glutes','hamstrings','calves']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.','Da un paso grande hacia adelante con una pierna, manteniendo el torso erguido.','Baja el cuerpo flexionando la rodilla delantera y la cadera, mientras mantienes la pierna trasera recta.','Continúa bajando hasta que el muslo delantero quede paralelo al suelo.','Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de pierna.']::text[],'Equipo: Barra',true,'0099','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0099-gGNQmVt.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0099-gGNQmVt.jpg','barbell',now(),now()),
('barbell sitted alternate leg raise','abs',array['hip flexors']::text[],'beginner','isolation',array['Siéntate en un banco con la espalda recta y sujeta una barra sobre los muslos.','Manteniendo las piernas rectas, levanta una pierna lo más alto posible mientras mantienes la otra pierna en el suelo.','Baja la pierna elevada y repite con la otra pierna.','Continúa alternando las piernas durante el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'2799','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2799-G7xoEzr.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2799-G7xoEzr.jpg','barbell',now(),now()),
('barbell sitted alternate leg raise (female)','abs',array['hip flexors','quadriceps']::text[],'beginner','compound',array['Siéntate en un banco con la espalda recta y sujeta una barra sobre los muslos.','Coloca las manos a los lados del banco para apoyarte.','Manteniendo las piernas rectas, levanta una pierna lo más alto posible manteniéndola paralela al suelo.','Baja la pierna y repite con la otra pierna.','Continúa alternando las piernas durante el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'2800','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2800-BCs0G2F.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2800-BCs0G2F.jpg','barbell',now(),now()),
('barbell skier','delts',array['triceps','core']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado.','Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.','Levanta simultáneamente la barra hacia los hombros mientras saltas ligeramente del suelo.','Al llegar a la parte más alta del movimiento, invierte rápidamente el movimiento y baja la barra de nuevo a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0100','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0100-4Leypho.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0100-4Leypho.jpg','barbell',now(),now()),
('barbell speed squat','glutes',array['quadriceps','hamstrings','calves']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.','Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.','Activa el core y mantén el pecho elevado mientras llevas las caderas hacia atrás y hacia abajo, como si te sentaras en una silla.','Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.','Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte más alta.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0101','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0101-euI1BwR.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0101-euI1BwR.jpg','barbell',now(),now()),
('barbell split squat v. 2','quads',array['glutes','hamstrings','calves']::text[],'beginner','compound',array['Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.','Da un paso grande hacia adelante con el pie derecho, manteniendo el torso erguido.','Baja el cuerpo flexionando las rodillas y las caderas hasta que el muslo derecho quede paralelo al suelo.','Haz una pausa breve, luego empuja con el talón derecho para volver a la posición inicial.','Repite con la pierna izquierda adelante el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'2810','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2810-HBYyX94.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2810-HBYyX94.jpg','barbell',now(),now()),
('barbell squat (on knees)','quads',array['glutes','hamstrings','calves']::text[],'beginner','compound',array['Comienza arrodillado en el suelo con las rodillas separadas a la altura de las caderas y las puntas de los pies apuntando hacia adelante.','Coloca una barra sobre los hombros, sujetándola con agarre prono y las manos un poco más separadas que el ancho de los hombros.','Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo flexionando las rodillas, manteniendo la espalda recta.','Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.','Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0102','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0102-oR7O9LW.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0102-oR7O9LW.jpg','barbell',now(),now()),
('barbell squat jump step rear lunge','quads',array['glutes','hamstrings','calves']::text[],'beginner','compound',array['Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.','Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.','Impúlsate explosivamente hacia arriba, saltando del suelo lo más alto que puedas.','Aterriza suavemente sobre los pies y de inmediato retrocede con una pierna hacia una zancada inversa.','Baja el cuerpo hasta que el muslo delantero quede paralelo al suelo, manteniendo la espalda recta.','Empuja con el talón delantero para volver a la posición inicial.','Repite la secuencia de salto y zancada con la otra pierna.','Continúa alternando las piernas durante el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'2798','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2798-RYcV1kH.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2798-RYcV1kH.jpg','barbell',now(),now()),
('barbell standing ab rollerout','abs',array['shoulders','lower back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con ambas manos frente a los muslos.','Activa el core y enrolla lentamente la barra hacia el suelo, manteniendo la espalda recta y los brazos extendidos.','Continúa enrollando la barra hacia adelante hasta que el cuerpo esté completamente extendido y las manos queden justo sobre la cabeza.','Haz una pausa breve, luego enrolla lentamente la barra de vuelta hacia los muslos, manteniendo el control y el core activado.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0103','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0103-xnInPfE.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0103-xnInPfE.jpg','barbell',now(),now()),
('barbell standing back wrist curl','forearms',array['biceps','shoulders']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono.','Apoya la barra sobre el dorso de las manos con las palmas hacia abajo y los dedos apuntando hacia el cuerpo.','Manteniendo los brazos superiores quietos, exhala y flexiona las muñecas hacia arriba lo más posible.','Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0104','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0104-2qTvJAZ.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0104-2qTvJAZ.jpg','barbell',now(),now()),
('barbell standing bradford press','delts',array['triceps','upper back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra frente a los hombros con agarre prono.','Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.','Baja la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0105','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0105-dCPESfR.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0105-dCPESfR.jpg','barbell',now(),now()),
('barbell standing calf raise','calves',array['hamstrings','glutes']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y coloca una barra sobre la parte superior de la espalda.','Levanta los talones del suelo lo más alto posible, apoyándote solo en las puntas de los pies.','Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1372','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1372-8ozhUIZ.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1372-8ozhUIZ.jpg','barbell',now(),now()),
('barbell standing close grip curl','biceps',array['forearms']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre supino, manos juntas.','Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.','Exhala al flexionar el peso contrayendo los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.','Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.','Inhala mientras comienzas a llevar lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0106','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0106-4dUn2iv.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0106-4dUn2iv.jpg','barbell',now(),now()),
('barbell standing close grip military press','delts',array['triceps','upper back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, manos un poco más juntas que el ancho de los hombros.','Levanta la barra hasta la altura de los hombros, manteniendo los codos cerca del cuerpo.','Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.','Baja la barra de nuevo a la altura de los hombros.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1456','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1456-wdRZISl.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1456-wdRZISl.jpg','barbell',now(),now()),
('barbell standing concentration curl','biceps',array['forearms']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con una mano, con la palma hacia arriba.','Apoya la otra mano sobre el muslo para mayor estabilidad.','Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro.','Haz una pausa breve en la parte alta, apretando los bíceps.','Inhala y baja lentamente el peso de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de brazo.']::text[],'Equipo: Barra',true,'2414','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2414-vsMcDi9.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2414-vsMcDi9.jpg','barbell',now(),now()),
('barbell standing front raise over head','delts',array['triceps','upper back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra frente a los muslos con agarre prono.','Mantén la espalda recta y activa el core.','Levanta lentamente la barra frente a ti, manteniendo los brazos rectos y las palmas hacia abajo.','Continúa levantando hasta que la barra quede ligeramente por encima del nivel de los hombros.','Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0107','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0107-S8mo30S.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0107-S8mo30S.jpg','barbell',now(),now()),
('barbell standing leg calf raise','calves',array['hamstrings','glutes']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y coloca una barra sobre la parte superior de la espalda.','Levanta los talones del suelo lo más alto posible, usando las pantorrillas.','Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0108','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0108-rGwhJ5o.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0108-rGwhJ5o.jpg','barbell',now(),now()),
('barbell standing overhead triceps extension','triceps',array['shoulders']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono.','Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.','Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos.','Haz una pausa breve, luego levanta la barra de vuelta a la posición inicial extendiendo los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0109','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0109-dZl9Q27.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0109-dZl9Q27.jpg','barbell',now(),now()),
('barbell standing reverse grip curl','biceps',array['forearms']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.','Mantén los codos cerca del torso y los brazos superiores quietos.','Exhala y flexiona el peso contrayendo los bíceps, llevando la barra lo más cerca posible de los hombros.','Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.','Inhala y baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0110','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0110-LWuA3aZ.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0110-LWuA3aZ.jpg','barbell',now(),now()),
('barbell standing rocking leg calf raise','calves',array['hamstrings','quadriceps']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda.','Levanta los talones del suelo lo más alto posible, manteniendo el equilibrio sobre las puntas de los pies.','Baja lentamente los talones de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0111','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0111-6HiHHe0.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0111-6HiHHe0.jpg','barbell',now(),now()),
('barbell standing twist','abs',array['obliques','lower back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente al pecho con ambas manos, palmas hacia abajo.','Activa el core y mantén la espalda recta durante todo el ejercicio.','Gira lentamente el torso hacia la derecha, pivotando sobre los pies y las caderas, mientras mantienes estable la parte inferior del cuerpo.','Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.','Repite el giro hacia el lado izquierdo.','Continúa alternando los giros el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0112','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0112-yQe5HpE.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0112-yQe5HpE.jpg','barbell',now(),now()),
('barbell standing wide grip biceps curl','biceps',array['forearms']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre supino, manos más separadas que el ancho de los hombros.','Mantén la espalda recta y los codos cerca del torso.','Exhala y flexiona la barra hacia los hombros, manteniendo los brazos superiores quietos.','Haz una pausa breve en la parte alta, apretando los bíceps.','Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1629','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1629-faHKVkK.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1629-faHKVkK.jpg','barbell',now(),now()),
('barbell standing wide military press','delts',array['triceps','upper back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.','Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente por delante de la barra.','Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.','Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1457','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1457-Kyd9Rz5.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1457-Kyd9Rz5.jpg','barbell',now(),now()),
('barbell standing wide-grip curl','biceps',array['forearms','shoulders']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos más separadas que el ancho de los hombros.','Deja que la barra cuelgue a la longitud del brazo frente a los muslos, con las palmas mirando hacia afuera del cuerpo.','Manteniendo los brazos superiores quietos, exhala y flexiona la barra hacia arriba contrayendo los bíceps.','Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.','Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.','Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0113','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0113-NdIb5Z1.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0113-NdIb5Z1.jpg','barbell',now(),now()),
('barbell step-up','glutes',array['quadriceps','hamstrings','calves']::text[],'beginner','compound',array['Ponte de pie frente a un banco o escalón con una barra apoyada en la parte superior de la espalda.','Coloca un pie sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie.','Empuja con el talón y sube al banco o escalón, extendiendo completamente la cadera y la rodilla.','Haz una pausa breve en la parte más alta, luego baja de vuelta a la posición inicial.','Repite con la pierna contraria.','Continúa alternando las piernas durante el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0114','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0114-Kxquu2E.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0114-Kxquu2E.jpg','barbell',now(),now()),
('barbell stiff leg good morning','glutes',array['hamstrings','lower back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.','Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios.','Manteniendo la espalda recta, inclínate hacia adelante desde las caderas, empujando los glúteos hacia atrás.','Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.','Activa los glúteos y los isquiotibiales para volver a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0115','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0115-JrOHAZc.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0115-JrOHAZc.jpg','barbell',now(),now()),
('barbell straight leg deadlift','hamstrings',array['glutes','lower back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante.','Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.','Flexiona las caderas y baja la barra hacia el suelo, manteniendo la espalda recta y las rodillas ligeramente flexionadas.','Baja la barra hasta que sientas un estiramiento en los isquiotibiales.','Activa los isquiotibiales y los glúteos para levantar la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0116','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0116-hrVQWvE.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0116-hrVQWvE.jpg','barbell',now(),now()),
('barbell sumo deadlift','glutes',array['hamstrings','quadriceps','lower back']::text[],'beginner','compound',array['Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera.','Coloca una barra en el suelo frente a ti, centrada entre los pies.','Flexiona las rodillas y baja las caderas, manteniendo la espalda recta y el pecho elevado, para sujetar la barra con agarre prono.','Activa el core y empuja con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas simultáneamente.','Al levantar, mantén el pecho elevado y la espalda recta, y empuja las caderas hacia adelante para activar completamente los glúteos.','Haz una pausa breve en la parte más alta, luego baja lentamente la barra de vuelta a la posición inicial, manteniendo el control durante todo el movimiento.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0117','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0117-KgI0tqW.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0117-KgI0tqW.jpg','barbell',now(),now()),
('barbell thruster','delts',array['quadriceps','glutes','hamstrings','core']::text[],'beginner','compound',array['Comienza de pie con los pies separados a la altura de los hombros, sujetando una barra a la altura de los hombros con agarre prono.','Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.','Al llegar a la parte más baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando simultáneamente la barra por encima de la cabeza.','Baja la barra de nuevo a la altura de los hombros mientras vuelves a bajar a la posición de sentadilla.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'3305','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3305-f7Y9eDZ.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3305-f7Y9eDZ.jpg','barbell',now(),now()),
('barbell upright row','delts',array['traps','biceps']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros.','Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos.','Manteniendo la espalda recta y el core activado, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos.','Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0120','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0120-UDlhcO8.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0120-UDlhcO8.jpg','barbell',now(),now()),
('barbell upright row v. 2','delts',array['traps','biceps']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros.','Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos.','Manteniendo la espalda recta, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos.','Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0119','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0119-83HoW9X.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0119-83HoW9X.jpg','barbell',now(),now()),
('barbell upright row v. 3','delts',array['traps','biceps']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros.','Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos.','Manteniendo el core activado y la espalda recta, exhala mientras levantas la barra en línea recta hacia la barbilla, guiando el movimiento con los codos.','Haz una pausa breve en la parte más alta, luego inhala mientras bajas lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0121','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0121-fI18Rbc.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0121-fI18Rbc.jpg','barbell',now(),now()),
('barbell wide bench press','pectorals',array['shoulders','triceps']::text[],'beginner','compound',array['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.','Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.','Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.','Baja la barra lentamente hacia el pecho, manteniendo los codos ligeramente abiertos hacia afuera.','Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0122','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0122-JsKq9so.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0122-JsKq9so.jpg','barbell',now(),now()),
('barbell wide reverse grip bench press','pectorals',array['triceps','shoulders']::text[],'beginner','compound',array['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.','Sujeta la barra con un agarre supino amplio, un poco más separado que el ancho de los hombros.','Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.','Baja la barra lentamente hacia el pecho, manteniendo los codos pegados al cuerpo y las muñecas rectas.','Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'1258','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1258-945zpRg.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1258-945zpRg.jpg','barbell',now(),now()),
('barbell wide squat','quads',array['glutes','hamstrings','calves']::text[],'beginner','compound',array['Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.','Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.','Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.','Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.','Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0124','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0124-s7HX1BY.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0124-s7HX1BY.jpg','barbell',now(),now()),
('barbell wide-grip upright row','delts',array['traps','biceps']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos más separadas que el ancho de los hombros.','Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos.','Manteniendo la espalda recta, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos.','Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0123','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0123-RgJDRR1.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0123-RgJDRR1.jpg','barbell',now(),now()),
('barbell wrist curl','forearms',array['biceps','brachialis']::text[],'beginner','compound',array['Siéntate en un banco con los pies planos en el suelo y los antebrazos apoyados sobre los muslos, sujetando una barra con agarre supino.','Deja que la barra ruede hacia las puntas de los dedos, manteniendo las muñecas rectas.','Enrolla lentamente la barra hacia los antebrazos flexionando las muñecas.','Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0126','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0126-82LxxkW.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0126-82LxxkW.jpg','barbell',now(),now()),
('barbell wrist curl v. 2','forearms',array['biceps','brachialis']::text[],'beginner','compound',array['Siéntate en un banco con los pies planos sobre el suelo y las rodillas flexionadas.','Sujeta una barra con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros.','Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.','Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia los antebrazos.','Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0125','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0125-6kSxYnw.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0125-6kSxYnw.jpg','barbell',now(),now()),
('barbell zercher squat','glutes',array['quadriceps','hamstrings','calves','core']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.','Sujeta la barra en el pliegue de los codos, con las manos agarrando la barra para mayor estabilidad.','Activa el core y mantén el pecho elevado mientras bajas las caderas hacia atrás y hacia abajo en una posición de sentadilla.','Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.','Haz una pausa breve en la parte baja de la sentadilla y luego empuja con los talones para volver a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Barra',true,'0127','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0127-LSTChY9.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0127-LSTChY9.jpg','barbell',now(),now()),
('basic toe touch (male)','glutes',array['hamstrings','calves']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados.','Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas.','Extiende las manos hacia las puntas de los pies, manteniendo las piernas lo más rectas posible.','Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'3212','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3212-BbfB8Gb.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3212-BbfB8Gb.jpg','body weight',now(),now()),
('battling ropes','delts',array['forearms','core']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.','Sujeta un extremo de la cuerda en cada mano, con las palmas mirándose entre sí.','Levanta los brazos hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.','Comienza a hacer ondas alternas con las cuerdas, levantando y bajando rápidamente cada brazo.','Continúa durante el tiempo o el número de repeticiones deseado.']::text[],'Equipo: Cuerda',true,'0128','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0128-RJa4tCo.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0128-RJa4tCo.jpg','rope',now(),now()),
('bear crawl','cardiovascular system',array['core','shoulders','triceps']::text[],'beginner','cardio',array['Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas.','Levanta las rodillas ligeramente del suelo, manteniendo la espalda plana y el core activado.','Mueve la mano derecha y el pie izquierdo hacia adelante simultáneamente, seguido de la mano izquierda y el pie derecho.','Continúa avanzando a gatas, alternando los movimientos de manos y pies.','Mantén un ritmo constante y el core firme durante todo el ejercicio.','Continúa durante la distancia o el tiempo deseado.']::text[],'Equipo: Peso corporal',true,'3360','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3360-0Yz8WdV.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3360-0Yz8WdV.jpg','body weight',now(),now()),
('behind head chest stretch','pectorals',array['shoulders','triceps']::text[],'beginner','compound',array['Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.','Entrelaza los dedos detrás de la cabeza con los codos apuntando hacia afuera.','Junta lentamente los omóplatos y empuja el pecho hacia adelante.','Mantén el estiramiento durante 15-30 segundos.','Suelta el estiramiento y repite cuantas veces lo desees.']::text[],'Equipo: Máquina asistida',true,'1259','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1259-QoHIhPl.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1259-QoHIhPl.jpg','assisted',now(),now()),
('bench dip (knees bent)','triceps',array['chest','shoulders']::text[],'beginner','compound',array['Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas.','Desliza los glúteos fuera del banco y estira las piernas frente a ti, manteniendo los talones en el suelo.','Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.','Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'0129','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0129-RrLske5.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0129-RrLske5.jpg','body weight',now(),now()),
('bench dip on floor','triceps',array['chest','shoulders']::text[],'beginner','compound',array['Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante.','Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.','Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.','Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'1399','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1399-9RT8oQW.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1399-9RT8oQW.jpg','body weight',now(),now()),
('bench hip extension','glutes',array['hamstrings']::text[],'beginner','isolation',array['Siéntate en un banco con la espalda contra el banco y los pies planos en el suelo.','Coloca las manos sobre el banco para apoyarte.','Activa los glúteos y los isquiotibiales, luego levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.','Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'0130','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0130-u27Kcdz.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0130-u27Kcdz.jpg','body weight',now(),now()),
('bench pull-ups','lats',array['biceps','forearms']::text[],'beginner','compound',array['Colócate debajo de una barra o una superficie horizontal resistente que esté a la altura del pecho.','Sujeta la barra o la superficie con agarre prono, un poco más separado que el ancho de los hombros.','Cuélgate con los brazos completamente extendidos y el cuerpo recto.','Lleva el pecho hacia la barra o la superficie juntando los omóplatos y flexionando los codos.','Continúa tirando hasta que la barbilla quede por encima de la barra o la superficie.','Baja de nuevo a la posición inicial con control.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'3019','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3019-mExgrF9.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3019-mExgrF9.jpg','body weight',now(),now()),
('bent knee lying twist (male)','glutes',array['obliques','hip flexors']::text[],'beginner','compound',array['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.','Extiende los brazos hacia los lados, perpendiculares al cuerpo.','Manteniendo las rodillas juntas, bájalas lentamente hacia un lado, intentando tocar el suelo con las rodillas.','Haz una pausa breve, luego activa el core y levanta lentamente las rodillas de vuelta a la posición inicial.','Repite el movimiento hacia el otro lado.','Continúa alternando lados durante el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'3639','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3639-6sYyrRX.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3639-6sYyrRX.jpg','body weight',now(),now()),
('biceps leg concentration curl','biceps',array['forearms']::text[],'beginner','isolation',array['Siéntate en un banco con las piernas separadas y los pies planos en el suelo.','Sujeta una mancuerna con una mano y coloca el codo en la parte interna del muslo, justo por encima de la rodilla.','Con la palma hacia arriba, flexiona la mancuerna hacia el hombro manteniendo el brazo superior quieto.','Contrae el bíceps en la parte más alta del movimiento, luego baja lentamente la mancuerna de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de brazo.']::text[],'Equipo: Peso corporal',true,'1770','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1770-sJFIDIp.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1770-sJFIDIp.jpg','body weight',now(),now()),
('biceps narrow pull-ups','biceps',array['forearms','shoulders']::text[],'beginner','compound',array['Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros.','Activa el core y tira de tu cuerpo hacia la barra, enfocándote en usar los bíceps para levantar el cuerpo.','Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'0139','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0139-50BETrz.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0139-50BETrz.jpg','body weight',now(),now()),
('biceps pull-up','biceps',array['forearms','shoulders']::text[],'beginner','compound',array['Cuélgate de una barra de dominadas con las palmas mirando hacia afuera y las manos separadas a la altura de los hombros.','Activa el core y tira de tu cuerpo hacia arriba flexionando los codos, llevando el pecho hacia la barra.','Haz una pausa en la parte más alta del movimiento, luego baja lentamente de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'0140','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0140-guT8YnS.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0140-guT8YnS.jpg','body weight',now(),now()),
('body-up','triceps',array['chest','shoulders']::text[],'beginner','compound',array['Comienza colocando las manos sobre una superficie elevada, como un banco o unas barras paralelas, con las palmas hacia abajo y los dedos apuntando hacia adelante.','Extiende las piernas frente a ti, manteniendo los talones en el suelo y el cuerpo recto.','Baja el cuerpo flexionando los codos, manteniéndolos cerca del cuerpo, hasta que los brazos superiores queden paralelos al suelo.','Haz una pausa breve, luego empuja con las palmas para extender los brazos y levantar el cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'0137','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0137-U6G2gk9.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0137-U6G2gk9.jpg','body weight',now(),now()),
('bodyweight drop jump squat','glutes',array['quadriceps','hamstrings','calves']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros.','Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.','Salta hacia arriba explosivamente, extendiendo las caderas, las rodillas y los tobillos.','Mientras estás en el aire, junta rápidamente los pies.','Aterriza suavemente sobre las puntas de los pies y de inmediato vuelve a bajar a una posición de sentadilla.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'3543','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3543-wfotm7S.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3543-wfotm7S.jpg','body weight',now(),now()),
('bodyweight incline side plank','abs',array['obliques','shoulders']::text[],'beginner','compound',array['Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.','Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados.','Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.','Mantén esta posición durante el tiempo deseado.','Baja las caderas de nuevo al suelo y repite hacia el otro lado.']::text[],'Equipo: Peso corporal',true,'3544','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3544-5VXmnV5.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3544-5VXmnV5.jpg','body weight',now(),now()),
('bodyweight kneeling triceps extension','triceps',array['shoulders','chest']::text[],'beginner','compound',array['Ponte de rodillas en el suelo con las rodillas separadas a la altura de las caderas.','Coloca las manos en el suelo frente a ti, separadas a la altura de los hombros, con los dedos apuntando hacia adelante.','Extiende las piernas rectas detrás de ti, equilibrándote sobre las puntas de los pies y las manos, formando una línea recta desde la cabeza hasta los talones.','Flexiona los codos y baja la parte superior del cuerpo hacia el suelo, manteniendo los codos cerca del cuerpo.','Haz una pausa breve en la posición más baja, luego empuja con las manos para extender los brazos y volver a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'1771','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1771-s0HKO2I.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1771-s0HKO2I.jpg','body weight',now(),now()),
('bodyweight side lying biceps curl','biceps',array['forearms']::text[],'beginner','isolation',array['Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el brazo.','Mantén el brazo superior junto al cuerpo y flexiona el codo para llevar el antebrazo hacia el hombro.','Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'1769','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1769-gscGLOU.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1769-gscGLOU.jpg','body weight',now(),now()),
('bodyweight squatting row','upper back',array['biceps','shoulders']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, sujetando un objeto resistente o un entrenador de suspensión con los brazos extendidos.','Baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies.','Desde la posición de sentadilla, tira del cuerpo hacia arriba en dirección al objeto o al entrenador de suspensión, juntando los omóplatos.','Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'3168','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3168-3xK09Sk.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3168-3xK09Sk.jpg','body weight',now(),now()),
('bodyweight squatting row (with towel)','upper back',array['biceps','shoulders']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, sujetando una toalla frente a ti con las palmas hacia abajo.','Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.','Mientras bajas a la sentadilla, tira simultáneamente de la toalla hacia el pecho, juntando los omóplatos.','Haz una pausa breve en la parte más baja de la sentadilla, luego vuelve lentamente a la posición inicial mientras extiendes los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'3167','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3167-BReCuOn.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3167-BReCuOn.jpg','body weight',now(),now()),
('bodyweight standing calf raise','calves',array['ankles','feet']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.','Coloca las manos sobre una pared o superficie estable para mantener el equilibrio.','Levanta lentamente los talones del suelo, llevando el peso del cuerpo hacia las puntas de los pies.','Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'1373','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1373-bJYHBIN.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1373-bJYHBIN.jpg','body weight',now(),now()),
('bodyweight standing close-grip one arm row','upper back',array['biceps','forearms']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna en una mano con agarre neutro.','Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.','Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.','Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de lado.']::text[],'Equipo: Peso corporal',true,'3156','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3156-v2DfH14.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3156-v2DfH14.jpg','body weight',now(),now()),
('bodyweight standing close-grip row','upper back',array['biceps','forearms']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.','Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.','Extiende los brazos rectos frente a ti, sujetando la barra o las agarraderas con un agarre cerrado.','Tira de la barra o las agarraderas hacia el cuerpo, juntando los omóplatos.','Haz una pausa breve en la parte más alta del movimiento, luego suelta lentamente y vuelve a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'3158','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3158-tig3PXb.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3158-tig3PXb.jpg','body weight',now(),now()),
('bodyweight standing one arm row','upper back',array['biceps','forearms']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna con una mano.','Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.','Deja que la mancuerna cuelgue recta frente a ti, con el brazo completamente extendido.','Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo.','Junta los omóplatos en la parte superior del movimiento.','Baja la mancuerna de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de lado.']::text[],'Equipo: Peso corporal',true,'3162','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3162-xbkPfaw.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3162-xbkPfaw.jpg','body weight',now(),now()),
('bodyweight standing one arm row (with towel)','upper back',array['biceps','forearms']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una toalla con una mano.','Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.','Tira de la toalla hacia el pecho, juntando los omóplatos.','Haz una pausa breve en la parte más alta, luego baja lentamente la toalla de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[],'Equipo: Peso corporal',true,'3161','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3161-O4oIqQD.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3161-O4oIqQD.jpg','body weight',now(),now()),
('bodyweight standing row','upper back',array['biceps','shoulders']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.','Sujeta una barra o las agarraderas con agarre prono, palmas hacia abajo.','Mantén la espalda recta y el core activado.','Tira de la barra o las agarraderas hacia el cuerpo, juntando los omóplatos.','Haz una pausa breve en la parte alta del movimiento.','Suelta lentamente y extiende los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'3166','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3166-wd4ds3s.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3166-wd4ds3s.jpg','body weight',now(),now()),
('bodyweight standing row (with towel)','upper back',array['biceps','shoulders']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta una toalla frente a ti con ambas manos.','Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.','Tira de la toalla hacia el pecho, juntando los omóplatos.','Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'3165','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3165-uTv34oq.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3165-uTv34oq.jpg','body weight',now(),now()),
('bottoms-up','abs',array['obliques','hip flexors']::text[],'beginner','compound',array['Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.','Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies fuera del suelo.','Activando el abdomen, levanta las caderas del suelo, llevando las rodillas hacia la cabeza.','Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'0138','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0138-CI6baTY.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0138-CI6baTY.jpg','body weight',now(),now()),
('box jump down with one leg stabilization','calves',array['quadriceps','hamstrings','glutes']::text[],'beginner','compound',array['Ponte de pie frente a una caja o plataforma con los pies separados a la altura de los hombros.','Flexiona las rodillas y salta sobre la caja, aterrizando suavemente con un pie sobre la caja y el otro pie colgando del borde.','Estabilízate sobre la caja con el pie que está sobre ella, mientras mantienes el otro pie fuera del suelo.','Mantén esta posición durante unos segundos, activando los músculos de la pantorrilla para conservar el equilibrio.','Baja lentamente con el pie que está sobre la caja, volviendo a la posición inicial.','Repite el ejercicio con la otra pierna.']::text[],'Equipo: Peso corporal',true,'1374','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1374-iPm26QU.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1374-iPm26QU.jpg','body weight',now(),now()),
('bridge - mountain climber (cross body)','abs',array['glutes','quadriceps','hamstrings','shoulders','triceps']::text[],'beginner','compound',array['Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.','Activa el core y levanta el pie derecho del suelo, llevando la rodilla derecha hacia el codo izquierdo.','Vuelve a colocar el pie derecho en la posición inicial y repite el movimiento llevando el pie izquierdo hacia el codo derecho.','Continúa alternando los lados, moviéndote a un ritmo controlado.','Mantén las caderas niveladas y evita levantarlas demasiado alto o dejarlas caer demasiado bajo.','Mantén un patrón de respiración constante durante todo el ejercicio.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'2466','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2466-9c6T1YX.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2466-9c6T1YX.jpg','body weight',now(),now()),
('burpee','cardiovascular system',array['quadriceps','hamstrings','calves','shoulders','chest']::text[],'beginner','cardio',array['Comienza de pie con los pies separados a la altura de los hombros.','Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y colocando las manos en el suelo frente a ti.','Lleva los pies hacia atrás de una patada hasta una posición de flexión de brazos.','Realiza una flexión de brazos, manteniendo el cuerpo en línea recta.','Salta con los pies de vuelta a la posición de sentadilla.','Salta hacia arriba explosivamente, llevando los brazos por encima de la cabeza.','Aterriza suavemente y baja de inmediato a una posición de sentadilla para comenzar la siguiente repetición.']::text[],'Equipo: Peso corporal',true,'1160','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1160-dK9394r.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1160-dK9394r.jpg','body weight',now(),now()),
('butt-ups','abs',array['hip flexors','lower back']::text[],'beginner','compound',array['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.','Coloca las manos a los lados, con las palmas hacia abajo.','Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho.','En la parte más alta del movimiento, contrae el abdomen y haz una pausa breve.','Baja lentamente las piernas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Peso corporal',true,'0870','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0870-qcNN2FN.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0870-qcNN2FN.jpg','body weight',now(),now()),
('butterfly yoga pose','adductors',array['hamstrings','groin']::text[],'beginner','compound',array['Siéntate en el suelo con las piernas extendidas frente a ti.','Flexiona las rodillas y junta las plantas de los pies, dejando que las rodillas caigan hacia los lados.','Sujétate los tobillos o los pies con las manos.','Siéntate erguido y alarga la columna.','Presiona suavemente las rodillas hacia el suelo, sintiendo un estiramiento en la parte interna de los muslos.','Mantén esta posición durante unas cuantas respiraciones.','Para liberar, lleva lentamente las rodillas hacia arriba de nuevo y extiende las piernas.']::text[],'Equipo: Peso corporal',true,'1494','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1494-bWlZvXh.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1494-bWlZvXh.jpg','body weight',now(),now()),
('cable alternate shoulder press','delts',array['triceps','upper back']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas de la máquina de cable con agarre prono.','Coloca las manos a la altura de los hombros, con las palmas mirando hacia adelante.','Mantén el core activado y la espalda recta.','Empuja una agarradera hacia arriba y hacia adelante hasta que el brazo quede completamente extendido.','Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial.','Repite con el otro brazo.','Alterna entre los brazos el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0148','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0148-KHPZL0b.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0148-KHPZL0b.jpg','cable',now(),now()),
('cable alternate triceps extension','triceps',array['shoulders']::text[],'beginner','isolation',array['Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.','Sujeta la agarradera del cable con la mano derecha y levanta el brazo de modo que el brazo superior quede paralelo al suelo y el codo flexionado en un ángulo de 90 grados.','Mantén el brazo superior quieto y extiende el antebrazo hacia atrás, estirando completamente el brazo.','Haz una pausa por un momento, luego regresa lentamente a la posición inicial.','Repite con el brazo izquierdo.','Continúa alternando los brazos durante el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0149','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0149-Gchi5Tr.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0149-Gchi5Tr.jpg','cable',now(),now()),
('cable assisted inverse leg curl','hamstrings',array['glutes','calves']::text[],'beginner','compound',array['Ajusta la máquina de cable de modo que el accesorio para el tobillo quede en la posición más baja.','Túmbate boca abajo en el banco con las piernas rectas y el accesorio para el tobillo sujeto a los tobillos.','Sujétate de las agarraderas del banco para mantener la estabilidad.','Manteniendo quieta la parte superior del cuerpo, exhala y flexiona las piernas hacia los glúteos doblando las rodillas.','Haz una pausa breve en la parte más alta del movimiento, contrayendo los isquiotibiales.','Inhala y baja lentamente las piernas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'3235','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3235-zHEpuuc.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3235-zHEpuuc.jpg','cable',now(),now()),
('cable bar lateral pulldown','lats',array['biceps','rhomboids','rear deltoids']::text[],'beginner','compound',array['Ajusta la polea del cable a una posición alta y coloca una barra recta.','Siéntate frente a la máquina de cable con los pies planos en el suelo y las rodillas ligeramente flexionadas.','Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.','Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando un ligero arco en la zona lumbar.','Tira de la barra hacia el pecho, guiando el movimiento con los codos y juntando los omóplatos.','Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente la barra a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0150','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0150-eYnzaCm.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0150-eYnzaCm.jpg','cable',now(),now()),
('cable bench press','pectorals',array['triceps','shoulders']::text[],'beginner','compound',array['Ajusta la máquina de cable a la altura del pecho y coloca las agarraderas.','Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.','Sujeta las agarraderas con agarre prono y da un paso hacia adelante para crear tensión en los cables.','Coloca los pies firmemente en el suelo y activa el core.','Flexiona los codos y lleva las manos a la altura de los hombros, manteniendo los codos en un ángulo de 90 grados.','Empuja las agarraderas hacia adelante, extendiendo completamente los brazos frente a ti.','Haz una pausa breve, luego invierte lentamente el movimiento, llevando las manos de vuelta a la altura de los hombros.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0151','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0151-7xI5MXA.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0151-7xI5MXA.jpg','cable',now(),now()),
('cable close grip curl','biceps',array['forearms']::text[],'beginner','isolation',array['Coloca una barra recta en una máquina de cable con polea baja.','Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.','Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.','Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.','Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps.','Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.','Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'1630','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1630-BCGQ6J5.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1630-BCGQ6J5.jpg','cable',now(),now()),
('cable concentration curl','biceps',array['forearms']::text[],'beginner','isolation',array['Siéntate en un banco o silla con los pies planos en el suelo y las rodillas ligeramente flexionadas.','Sujeta la agarradera del cable con agarre supino y apoya el codo en la parte interna del muslo.','Manteniendo el brazo superior quieto, exhala y flexiona la agarradera del cable hacia el hombro contrayendo el bíceps.','Haz una pausa breve en la parte más alta del movimiento, luego inhala y baja lentamente la agarradera del cable de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de brazo.']::text[],'Equipo: Polea',true,'1631','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1631-NvfE43H.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1631-NvfE43H.jpg','cable',now(),now()),
('cable concentration extension (on knee)','triceps',array['forearms']::text[],'beginner','isolation',array['Siéntate en un banco o silla con las rodillas flexionadas y los pies planos en el suelo.','Sujeta la agarradera del cable con la mano derecha y coloca el codo en la parte interna de la rodilla derecha.','Extiende completamente el brazo, manteniendo el codo quieto y cerca de la rodilla.','Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de lado.']::text[],'Equipo: Polea',true,'0152','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0152-Db7eEgw.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0152-Db7eEgw.jpg','cable',now(),now()),
('cable cross-over lateral pulldown','lats',array['biceps','rhomboids','rear deltoids']::text[],'beginner','compound',array['Coloca una agarradera de cable en cada lado de una máquina de cable a la altura de los hombros.','Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros.','Sujeta las agarraderas con agarre prono y da un paso hacia atrás para crear tensión en los cables.','Inclínate ligeramente hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.','Tira de las agarraderas hacia abajo y a través del cuerpo, juntando los omóplatos.','Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0153','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0153-OQ1otBN.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0153-OQ1otBN.jpg','cable',now(),now()),
('cable cross-over revers fly','delts',array['rhomboids','trapezius']::text[],'beginner','compound',array['Coloca una agarradera en D en cada cable de polea baja y ponte de pie en el centro de la máquina de cable cruzado.','Sujeta las agarraderas con agarre prono (palmas hacia abajo) y da un paso hacia adelante, colocando los pies separados a la altura de los hombros.','Flexiona ligeramente las rodillas e inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el abdomen activado.','Con los brazos extendidos hacia los lados y ligeramente flexionados en los codos, exhala y junta los omóplatos mientras tiras de los cables hacia atrás y hacia arriba en un movimiento de apertura inversa.','Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0154','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0154-aqvSOQE.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0154-aqvSOQE.jpg','cable',now(),now()),
('cable cross-over variation','pectorals',array['deltoids','triceps']::text[],'beginner','compound',array['Ajusta las poleas del cable a la altura del pecho.','Ponte de pie en el centro de la máquina de cable con un pie delante del otro.','Sujeta las agarraderas con las palmas hacia abajo y los brazos extendidos hacia los lados.','Da un paso hacia adelante, manteniendo los brazos ligeramente flexionados.','Con una ligera flexión en los codos, junta las manos frente al pecho.','Haz una pausa breve, luego vuelve lentamente los brazos a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0155','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0155-0CXGHya.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0155-0CXGHya.jpg','cable',now(),now()),
('cable curl','biceps',array['forearms']::text[],'beginner','isolation',array['Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.','Sujeta el accesorio del cable con agarre supino, palmas hacia arriba.','Mantén los codos cerca de los costados y los brazos superiores quietos.','Exhala y flexiona el accesorio del cable hacia los hombros, contrayendo los bíceps.','Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.','Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0868','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0868-G08RZcQ.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0868-G08RZcQ.jpg','cable',now(),now()),
('cable deadlift','glutes',array['hamstrings','quadriceps','lower back']::text[],'beginner','compound',array['Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.','Flexiona las caderas y las rodillas, bajando el torso hasta que la espalda quede paralela al suelo.','Sujeta las agarraderas del cable con agarre prono, manteniendo los brazos rectos y los hombros hacia atrás.','Activa los glúteos y los isquiotibiales para levantar las agarraderas del cable, extendiendo las caderas y poniéndote de pie.','Haz una pausa breve en la parte más alta, luego baja lentamente las agarraderas del cable de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0157','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0157-eGDudUV.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0157-eGDudUV.jpg','cable',now(),now()),
('cable decline fly','pectorals',array['shoulders','triceps']::text[],'beginner','compound',array['Ajusta la máquina de cable a una posición declinada.','Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.','Sujeta las agarraderas con las palmas hacia adelante y los brazos extendidos rectos frente a ti.','Manteniendo una ligera flexión en los codos, abre los brazos hacia los lados con un movimiento controlado.','Haz una pausa breve en la posición completamente extendida, luego vuelve lentamente a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0158','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0158-7saC5zz.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0158-7saC5zz.jpg','cable',now(),now()),
('cable decline one arm press','pectorals',array['triceps','shoulders']::text[],'beginner','compound',array['Ajusta la máquina de cable a una posición declinada.','Ponte de pie de espaldas a la máquina y sujeta la agarradera con una mano.','Colócate con la espalda contra el banco declinado y el brazo extendido recto frente a ti.','Flexiona el codo y baja la agarradera hacia el pecho, manteniendo el brazo superior quieto.','Haz una pausa breve en la parte más baja, luego empuja la agarradera de vuelta hacia la posición inicial.','Repite el número de repeticiones deseado, luego cambia de brazo.']::text[],'Equipo: Polea',true,'1260','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1260-KHGNa16.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1260-KHGNa16.jpg','cable',now(),now()),
('cable decline press','pectorals',array['triceps','shoulders']::text[],'beginner','compound',array['Ajusta la máquina de cable a una posición declinada.','Siéntate en el banco declinado frente a la máquina de cable.','Sujeta las agarraderas con agarre prono y colócalas a la altura del pecho.','Mantén los pies planos en el suelo y la espalda firmemente apoyada en el banco.','Exhala y empuja las agarraderas alejándolas del cuerpo, extendiendo completamente los brazos.','Haz una pausa breve al final del movimiento, contrayendo los músculos del pecho.','Inhala y vuelve lentamente las agarraderas a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'1261','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1261-2Pya1cP.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1261-2Pya1cP.jpg','cable',now(),now()),
('cable decline seated wide-grip row','upper back',array['biceps','forearms']::text[],'beginner','compound',array['Siéntate en el banco declinado frente a la máquina de cable con los pies firmemente colocados en los reposapiés.','Sujeta el accesorio del cable con un agarre prono amplio, palmas hacia abajo.','Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado.','Tira del cable hacia la parte inferior del pecho, juntando los omóplatos.','Haz una pausa breve en el punto máximo de la contracción, luego suelta lentamente el cable de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0159','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0159-kesXOpB.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0159-kesXOpB.jpg','cable',now(),now()),
('cable drag curl','biceps',array['forearms']::text[],'beginner','isolation',array['Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.','Sujeta el accesorio del cable con agarre supino, palmas hacia arriba, y los brazos completamente extendidos.','Manteniendo los brazos superiores quietos, exhala y flexiona el accesorio del cable hacia los hombros contrayendo los bíceps.','Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.','Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'1632','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1632-dXz8zjF.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1632-dXz8zjF.jpg','cable',now(),now()),
('cable floor seated wide-grip row','upper back',array['biceps','forearms']::text[],'beginner','compound',array['Siéntate en el suelo con las piernas extendidas y la espalda recta.','Coloca una agarradera de cable en una polea baja y ubica la máquina de cable detrás de ti.','Sujeta la agarradera con un agarre prono amplio, palmas hacia abajo.','Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el pecho elevado.','Tira de la agarradera hacia la cintura, juntando los omóplatos.','Haz una pausa breve en la parte más alta del movimiento, luego suelta lentamente la agarradera de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0160','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0160-veXwo0D.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0160-veXwo0D.jpg','cable',now(),now()),
('cable forward raise','delts',array['triceps','forearms']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.','Sujeta la agarradera del cable con agarre prono, palmas hacia abajo, y los brazos completamente extendidos frente a ti.','Manteniendo los brazos rectos, levanta la agarradera del cable hasta la altura de los hombros.','Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0161','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0161-hvHhCv8.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0161-hvHhCv8.jpg','cable',now(),now()),
('cable front raise','delts',array['triceps','forearms']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono.','Mantén la espalda recta y el core activado.','Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo.','Continúa levantando hasta que los brazos queden paralelos al suelo.','Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0162','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0162-u2X71Np.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0162-u2X71Np.jpg','cable',now(),now()),
('cable front shoulder raise','delts',array['trapezius','biceps']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono.','Mantén la espalda recta y el core activado.','Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo.','Continúa levantando hasta que los brazos queden paralelos al suelo.','Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0164','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0164-mTT3KLn.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0164-mTT3KLn.jpg','cable',now(),now()),
('cable hammer curl (with rope)','biceps',array['forearms']::text[],'beginner','isolation',array['Ponte de pie con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.','Sujeta el accesorio de cuerda del cable con agarre supino, palmas mirándose entre sí, y los brazos completamente extendidos.','Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.','Continúa levantando el accesorio de cuerda del cable hasta que los bíceps estén completamente contraídos y la cuerda esté a la altura de los hombros.','Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.','Inhala y comienza a bajar lentamente el accesorio de cuerda del cable de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0165','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0165-HPlPoQA.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0165-HPlPoQA.jpg','cable',now(),now()),
('cable high pulley overhead tricep extension','triceps',array['shoulders']::text[],'beginner','isolation',array['Coloca una cuerda en una polea alta y ponte de pie de espaldas a la máquina.','Sujeta la cuerda con ambas manos y extiende los brazos por encima de la cabeza.','Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil.','Baja lentamente la cuerda detrás de la cabeza flexionando los codos.','Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'1722','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1722-1xHyxys.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1722-1xHyxys.jpg','cable',now(),now()),
('cable high row (kneeling)','upper back',array['biceps','shoulders']::text[],'beginner','compound',array['Sujeta una barra recta a una máquina de cable a la altura del pecho.','Ponte de rodillas frente a la máquina de cable y agarra la barra con un agarre prono, con las manos separadas a la altura de los hombros.','Siéntate sobre los talones, manteniendo la espalda recta y el core activado.','Jala la barra hacia la parte superior del abdomen, apretando los omóplatos entre sí.','Haz una pausa por un momento en la parte más alta del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0167','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0167-ZSJNetl.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0167-ZSJNetl.jpg','cable',now(),now()),
('cable hip adduction','adductors',array['glutes','quadriceps']::text[],'beginner','compound',array['Sujeta el manguito de tobillo a tu tobillo y ponte de pie frente a la máquina de cable.','Colócate lo suficientemente alejado de la máquina para que haya tensión en el cable.','Coloca las manos sobre la máquina para apoyarte.','Manteniendo la pierna recta, mueve lentamente la pierna por delante del cuerpo hacia la línea media.','Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0168','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0168-hBGWILP.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0168-hBGWILP.jpg','cable',now(),now()),
('cable incline bench press','pectorals',array['deltoids','triceps']::text[],'beginner','compound',array['Ajusta el banco a una inclinación de 45 grados.','Sujeta las agarraderas del cable a las poleas altas.','Siéntate en el banco frente a la máquina de cable con los pies apoyados planos en el suelo.','Sujeta las agarraderas con un agarre prono y llévalas a la altura de los hombros.','Empuja las agarraderas hacia adelante y hacia arriba hasta que los brazos queden completamente extendidos.','Haz una pausa por un momento y luego baja lentamente las agarraderas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0169','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0169-Vh0GsK4.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0169-Vh0GsK4.jpg','cable',now(),now()),
('cable incline bench row','upper back',array['biceps','rear deltoids']::text[],'beginner','compound',array['Coloca un banco inclinado a un ángulo de 45 grados y sujeta una agarradera de cable a la polea baja.','Siéntate en el banco frente a la máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.','Sujeta la agarradera del cable con un agarre prono y extiende los brazos completamente frente a ti.','Inclínate hacia adelante desde las caderas manteniendo la espalda recta y el core activado.','Jala la agarradera del cable hacia el pecho retrayendo los omóplatos y flexionando los codos.','Aprieta los músculos de la espalda en la parte más alta del movimiento y luego extiende lentamente los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'1318','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1318-yaMIo4D.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1318-yaMIo4D.jpg','cable',now(),now()),
('cable incline fly','pectorals',array['deltoids','triceps']::text[],'beginner','compound',array['Ajusta la máquina de cable a una posición baja y sujeta las agarraderas.','Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo.','Sujeta las agarraderas con un agarre prono y extiende los brazos rectos frente a ti.','Manteniendo una ligera flexión en los codos, abre los brazos hacia los lados con un movimiento controlado.','Haz una pausa breve en la posición completamente extendida, luego vuelve lentamente a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0171','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0171-tBWXbIT.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0171-tBWXbIT.jpg','cable',now(),now()),
('cable incline fly (on stability ball)','pectorals',array['deltoids','triceps']::text[],'beginner','compound',array['Coloca un balón de estabilidad en un ángulo inclinado.','Sujeta las agarraderas del cable a las poleas altas de una máquina de cable.','Siéntate sobre el balón de estabilidad de espaldas a la máquina, con los pies firmemente apoyados en el suelo.','Sujeta las agarraderas del cable con un agarre prono, con las palmas hacia adelante.','Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado.','Con un movimiento controlado, lleva los brazos hacia los lados, manteniendo una ligera flexión en los codos.','Continúa el movimiento hasta que los brazos queden paralelos al suelo.','Haz una pausa por un momento, luego regresa lentamente a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0170','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0170-27NNGFr.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0170-27NNGFr.jpg','cable',now(),now()),
('cable incline pushdown','lats',array['triceps','shoulders']::text[],'beginner','compound',array['Sujeta una barra recta a una máquina de cable con polea alta.','Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.','Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.','Inclínate ligeramente hacia adelante y mantén la espalda recta.','Jala la barra hacia abajo en dirección a tus muslos extendiendo los codos.','Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0172','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0172-1PK5Uo3.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0172-1PK5Uo3.jpg','cable',now(),now()),
('cable incline triceps extension','triceps',array['shoulders']::text[],'beginner','isolation',array['Ajusta la máquina de cable a una posición de polea baja.','Sujeta una barra recta al cable.','Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.','Sujeta la barra con un agarre prono y extiende los brazos rectos por encima de la cabeza.','Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado.','Flexiona los codos y baja la barra detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas.','Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0173','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0173-Hx1WC8I.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0173-Hx1WC8I.jpg','cable',now(),now()),
('cable judo flip','abs',array['obliques','shoulders']::text[],'beginner','compound',array['Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.','Sujeta la agarradera del cable con ambas manos a la altura del pecho, con las palmas hacia abajo.','Activa el core y rota el torso hacia la derecha, jalando el cable a través del cuerpo.','Mientras rotas, gira el pie de atrás y permite que las caderas roten de forma natural.','Extiende los brazos completamente y termina el movimiento llevando la agarradera del cable por encima del hombro.','Vuelve a la posición inicial revirtiendo el movimiento, rotando el torso de regreso al centro.','Repite el movimiento en el lado opuesto.','Continúa alternando lados durante el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0174','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0174-MvQPqVW.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0174-MvQPqVW.jpg','cable',now(),now()),
('cable kickback','triceps',array['shoulders']::text[],'beginner','isolation',array['Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.','Sujeta la agarradera del cable con la mano derecha y retrocede un paso para crear tensión en el cable.','Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.','Mantén la parte superior del brazo cerca del cuerpo y el codo flexionado en un ángulo de 90 grados.','Extiende el antebrazo hacia atrás, enderezando el brazo por completo.','Haz una pausa por un momento, luego regresa lentamente a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de lado.']::text[],'Equipo: Polea',true,'0860','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0860-HEJ6DIX.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0860-HEJ6DIX.jpg','cable',now(),now()),
('cable kneeling crunch','abs',array['obliques']::text[],'beginner','isolation',array['Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas de espaldas a la máquina.','Sujeta la agarradera de cuerda con ambas manos y colócala detrás de la cabeza, manteniendo los codos hacia afuera a los lados.','Manteniendo las caderas inmóviles, flexiona la cintura y encoge el torso hacia los muslos.','Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0175','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0175-WW95auq.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0175-WW95auq.jpg','cable',now(),now()),
('cable kneeling rear delt row (with rope) (male)','delts',array['trapezius','rhomboids','biceps']::text[],'beginner','compound',array['Sujeta una agarradera de cuerda a una polea baja y ponte de rodillas frente a la máquina.','Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra) y extiende los brazos completamente frente a ti.','Manteniendo la espalda recta y el core activado, jala la cuerda hacia el cuerpo retrayendo los omóplatos.','Aprieta los omóplatos al final del movimiento y mantén la posición por una breve pausa.','Libera lentamente la tensión y vuelve a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'3697','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3697-G61cXLk.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3697-G61cXLk.jpg','cable',now(),now()),
('cable kneeling triceps extension','triceps',array['shoulders']::text[],'beginner','isolation',array['Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas frente a la máquina de cable.','Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra) y lleva las manos a los lados de la cabeza.','Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil durante todo el ejercicio.','Extiende los antebrazos contrayendo los tríceps hasta que los brazos queden completamente extendidos.','Haz una pausa por un momento y luego vuelve lentamente a la posición inicial flexionando los codos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0176','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0176-KWdF2JI.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0176-KWdF2JI.jpg','cable',now(),now()),
('cable lat pulldown full range of motion','lats',array['biceps','rhomboids','rear deltoids']::text[],'beginner','compound',array['Siéntate en la máquina de jalón al pecho con las rodillas colocadas debajo de las almohadillas.','Sujeta la barra del cable con un agarre prono, un poco más separado que el ancho de los hombros.','Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando un ligero arco en la zona lumbar.','Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí.','Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'2330','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2330-LEprlgG.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2330-LEprlgG.jpg','cable',now(),now()),
('cable lateral pulldown (with rope attachment)','lats',array['biceps','forearms']::text[],'beginner','compound',array['Sujeta un accesorio de cuerda a la máquina de cable en una posición alta.','Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.','Sujeta la cuerda con un agarre prono, con las palmas una frente a la otra.','Mantén la espalda recta e inclínate ligeramente hacia atrás.','Jala la cuerda hacia los costados, apretando los omóplatos entre sí.','Haz una pausa por un momento en la parte baja del movimiento.','Libera lentamente la tensión y permite que la cuerda vuelva a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0177','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0177-CuaWCmC.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0177-CuaWCmC.jpg','cable',now(),now()),
('cable lateral pulldown with v-bar','lats',array['biceps','forearms']::text[],'beginner','compound',array['Siéntate en la máquina de jalón de cable y agarra el accesorio en V con un agarre prono.','Ajusta la almohadilla de rodillas para que tus muslos queden asegurados debajo de ella.','Mantén la espalda recta e inclínate ligeramente hacia atrás.','Jala el accesorio en V hacia la parte superior del pecho manteniendo los codos cerca del cuerpo.','Aprieta los músculos de la espalda en la parte baja del movimiento.','Regresa lentamente el accesorio en V a la posición inicial y repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'2616','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2616-4c9BhzB.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2616-4c9BhzB.jpg','cable',now(),now()),
('cable lateral raise','delts',array['traps','triceps']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas del cable con un agarre prono.','Mantén los brazos rectos y el core activado.','Levanta los brazos hacia los lados hasta que queden paralelos al suelo.','Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0178','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0178-goJ6ezq.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0178-goJ6ezq.jpg','cable',now(),now()),
('cable low fly','pectorals',array['deltoids','triceps']::text[],'beginner','compound',array['Sujeta las agarraderas a las poleas bajas de una máquina de cable y selecciona un peso adecuado.','Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.','Sujeta las agarraderas con un agarre prono y extiende los brazos hacia los lados, manteniendo una ligera flexión en los codos.','Manteniendo el control, lleva lentamente los brazos hacia adelante con un movimiento amplio, cruzándolos frente al cuerpo.','Haz una pausa por un momento en el punto más alto del movimiento, sintiendo el estiramiento en los músculos del pecho.','Invierte el movimiento y regresa lentamente los brazos a la posición inicial, manteniendo la tensión en los músculos del pecho durante todo el recorrido.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0179','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0179-FVmZVhk.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0179-FVmZVhk.jpg','cable',now(),now()),
('cable low seated row','upper back',array['biceps','forearms']::text[],'beginner','compound',array['Siéntate en la máquina con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.','Sujeta las agarraderas con un agarre prono, con las palmas hacia abajo.','Mantén la espalda recta e inclínate ligeramente hacia adelante, manteniendo una ligera flexión en los codos.','Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.','Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0180','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0180-hvV79Si.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0180-hvV79Si.jpg','cable',now(),now()),
('cable lying bicep curl','biceps',array['forearms']::text[],'beginner','isolation',array['Coloca una barra recta en una máquina de cable con polea baja.','Túmbate boca arriba en un banco plano con los pies apoyados planos en el suelo.','Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.','Extiende los brazos por completo, manteniendo los codos cerca de los costados.','Manteniendo la parte superior de los brazos inmóvil, exhala y curva la barra hacia los hombros.','Haz una pausa breve en la parte alta, apretando los bíceps.','Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'1634','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1634-otqIxU4.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1634-otqIxU4.jpg','cable',now(),now()),
('cable lying close-grip curl','biceps',array['forearms']::text[],'beginner','isolation',array['Coloca una barra recta en una máquina de cable con polea baja.','Túmbate boca arriba en un banco plano con los pies apoyados planos en el suelo.','Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.','Extiende los brazos por completo, manteniendo los codos cerca de los costados.','Manteniendo la parte superior de los brazos inmóvil, curva la barra hacia el pecho contrayendo los bíceps.','Haz una pausa breve en la parte alta, apretando los bíceps.','Baja lentamente la barra de vuelta a la posición inicial, extendiendo los brazos por completo.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0182','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0182-61GrD55.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0182-61GrD55.jpg','cable',now(),now()),
('cable lying extension pullover (with rope attachment)','lats',array['triceps','shoulders']::text[],'beginner','compound',array['Sujeta una cuerda a una máquina de cable y coloca la polea en la posición más alta.','Túmbate en un banco con la cabeza orientada hacia la máquina de cable.','Sujeta la cuerda con ambas manos y extiende los brazos rectos por encima del pecho.','Manteniendo los brazos rectos, baja lentamente la cuerda detrás de la cabeza manteniendo el control.','Haz una pausa por un momento en la parte baja y luego sube lentamente la cuerda de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0184','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0184-Q2Eu1Ax.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0184-Q2Eu1Ax.jpg','cable',now(),now()),
('cable lying fly','pectorals',array['deltoids','triceps']::text[],'beginner','compound',array['Sujeta las agarraderas a los cables y túmbate boca arriba en un banco con los pies apoyados planos en el suelo.','Sujeta las agarraderas con las palmas una frente a la otra y los brazos extendidos rectos por encima del pecho.','Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho.','Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar los brazos a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0185','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0185-lJJ7Yq8.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0185-lJJ7Yq8.jpg','cable',now(),now()),
('cable lying triceps extension v. 2','triceps',array['shoulders']::text[],'beginner','isolation',array['Sujeta una agarradera de cuerda a una máquina de cable con polea baja.','Túmbate boca arriba en un banco plano con la cabeza orientada hacia la máquina de cable.','Sujeta la agarradera de cuerda con ambas manos, con las palmas una frente a la otra, y extiende los brazos rectos por encima del pecho.','Manteniendo la parte superior de los brazos inmóvil, baja lentamente la agarradera de cuerda hacia la frente flexionando los codos.','Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0186','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0186-uxJcFUU.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0186-uxJcFUU.jpg','cable',now(),now()),
('cable middle fly','pectorals',array['deltoids','triceps']::text[],'beginner','compound',array['Sujeta los cables a ambos lados de una máquina de cable a la altura del pecho.','Ponte de pie en el centro de la máquina con un pie ligeramente delante del otro.','Sujeta las agarraderas con un agarre prono y extiende los brazos hacia los lados.','Mantén una ligera flexión en los codos y conserva una leve inclinación hacia adelante.','Activa los músculos del pecho y lleva los brazos hacia adelante con un movimiento amplio.','Haz una pausa por un momento en el centro y luego regresa lentamente los brazos a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0188','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0188-xLYSdtg.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0188-xLYSdtg.jpg','cable',now(),now()),
('cable one arm bent over row','upper back',array['biceps','forearms']::text[],'beginner','compound',array['Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.','Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.','Sujeta la agarradera del cable con una mano, con la palma hacia adentro, y extiende el brazo por completo.','Jala la agarradera del cable hacia el cuerpo, manteniendo el codo cerca del costado, hasta que la mano llegue a la parte baja del pecho.','Haz una pausa por un momento y luego extiende lentamente el brazo de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de lado.']::text[],'Equipo: Polea',true,'0189','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0189-EIsE3u8.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0189-EIsE3u8.jpg','cable',now(),now()),
('cable one arm curl','biceps',array['forearms']::text[],'beginner','isolation',array['Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.','Sujeta la agarradera del cable con un agarre supino, con la palma hacia arriba.','Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro.','Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.','Repite el número de repeticiones deseado.']::text[],'Equipo: Polea',true,'0190','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0190-YTur5nR.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0190-YTur5nR.jpg','cable',now(),now()),
('cable one arm decline chest fly','pectorals',array['shoulders','triceps']::text[],'beginner','compound',array['Sujeta una agarradera en D a una máquina de cable con polea baja y coloca el banco en un ángulo declinado.','Túmbate en el banco con la cabeza orientada hacia la máquina y agarra la agarradera con la mano derecha.','Extiende el brazo recto por encima del pecho, manteniendo una ligera flexión en el codo.','Con un movimiento controlado, baja el brazo hacia el lado hasta que la mano quede alineada con el hombro.','Haz una pausa por un momento y luego invierte el movimiento para regresar el brazo a la posición inicial.','Repite el número de repeticiones deseado y luego cambia al brazo izquierdo y repite el ejercicio.']::text[],'Equipo: Polea',true,'1262','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1262-w4dLzSx.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1262-w4dLzSx.jpg','cable',now(),now()),
('cable one arm fly on exercise ball','pectorals',array['deltoids','triceps']::text[],'beginner','compound',array['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.','Sujeta una agarradera del cable con una mano y extiende el brazo hacia el lado, paralelo al suelo.','Mantén el codo ligeramente flexionado y la palma hacia adelante.','Lleva lentamente el brazo a través del cuerpo, apretando los músculos del pecho.','Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de lado.']::text[],'Equipo: Polea',true,'1263','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1263-hHy8tQG.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1263-hHy8tQG.jpg','cable',now(),now()),
('cable one arm incline fly on exercise ball','pectorals',array['deltoids','triceps']::text[],'beginner','compound',array['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado.','Sujeta una agarradera del cable con una mano, con el brazo extendido y la palma hacia adentro.','Manteniendo una ligera flexión en el codo, baja lentamente el brazo hacia el lado hasta que la mano quede alineada con el hombro.','Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar el brazo a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de brazo.']::text[],'Equipo: Polea',true,'1264','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1264-P14Dz9D.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1264-P14Dz9D.jpg','cable',now(),now()),
('cable one arm incline press','pectorals',array['deltoids','triceps']::text[],'beginner','compound',array['Ajusta la máquina de cable a una posición de polea baja.','Siéntate en un banco inclinado de espaldas a la máquina de cable.','Sujeta la agarradera con una mano y llévala hasta la altura del hombro.','Coloca los pies firmemente en el suelo y mantén una posición estable.','Empuja la agarradera hacia adelante y hacia arriba, extendiendo el brazo por completo.','Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de lado.']::text[],'Equipo: Polea',true,'1265','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1265-GKEH6jj.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1265-GKEH6jj.jpg','cable',now(),now()),
('cable one arm incline press on exercise ball','pectorals',array['shoulders','triceps']::text[],'beginner','compound',array['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado.','Sujeta una agarradera del cable con una mano y coloca el brazo en un ángulo de 90 grados con el codo flexionado.','Empuja la agarradera del cable hacia adelante y hacia arriba, extendiendo el brazo por completo.','Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[],'Equipo: Polea',true,'1266','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1266-6t00BsF.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1266-6t00BsF.jpg','cable',now(),now()),
('cable one arm lateral bent-over','pectorals',array['deltoids','trapezius']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, frente a una máquina de cable.','Sujeta la agarradera con una mano y retrocede un paso para crear tensión en el cable.','Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.','Extiende el brazo hacia el lado, paralelo al suelo, con una ligera flexión en el codo.','Regresa lentamente el brazo a la posición inicial, manteniendo el control durante todo el movimiento.','Repite el número de repeticiones deseado, luego cambia de lado.']::text[],'Equipo: Polea',true,'0191','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0191-dB07vDu.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0191-dB07vDu.jpg','cable',now(),now()),
('cable one arm lateral raise','delts',array['traps','triceps']::text[],'beginner','compound',array['Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable.','Sujeta la agarradera del cable con una mano, con la palma hacia abajo, y colócate lo suficientemente alejado de la máquina para que haya tensión en el cable.','Mantén el brazo recto y levántalo lentamente hacia el lado hasta que quede paralelo al suelo.','Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de lado.']::text[],'Equipo: Polea',true,'0192','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0192-wEulIzp.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0192-wEulIzp.jpg','cable',now(),now()),
('cable one arm preacher curl','biceps',array['forearms']::text[],'beginner','isolation',array['Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho.','Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.','Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott.','Mantén la espalda recta y el core activado.','Curva lentamente la agarradera del cable hacia el hombro, manteniendo la parte superior del brazo contra la almohadilla.','Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.','Baja lentamente la agarradera del cable de vuelta a la posición inicial.','Repite el número de repeticiones deseado.','Cambia de brazo y repite el ejercicio.']::text[],'Equipo: Polea',true,'1633','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1633-eHBlPsa.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1633-eHBlPsa.jpg','cable',now(),now()),
('cable one arm press on exercise ball','pectorals',array['shoulders','triceps']::text[],'beginner','compound',array['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.','Sujeta una agarradera del cable con una mano y coloca el brazo a la altura del pecho, con el codo flexionado.','Coloca la otra mano en la cadera para mantener el equilibrio.','Empuja la agarradera del cable hacia adelante, extendiendo el brazo por completo.','Haz una pausa por un momento, luego regresa lentamente a la posición inicial.','Repite el número de repeticiones deseado, luego cambia de brazo.']::text[],'Equipo: Polea',true,'1267','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1267-MKIelrR.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1267-MKIelrR.jpg','cable',now(),now()),
('cable one arm pulldown','lats',array['biceps','forearms']::text[],'beginner','compound',array['Sujeta una agarradera individual a una máquina de cable con polea alta.','Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.','Sujeta la agarradera con un agarre prono y extiende el brazo por completo.','Mantén la espalda recta y el core activado.','Jala la agarradera hacia abajo en dirección al costado, manteniendo el codo cerca del cuerpo.','Haz una pausa por un momento en la parte baja del movimiento, apretando el dorsal.','Suelta lentamente la agarradera de vuelta a la posición inicial.','Repite el número de repeticiones deseado.','Cambia de lado y repite el ejercicio con el otro brazo.']::text[],'Equipo: Polea',true,'3563','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3563-U5INZY6.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3563-U5INZY6.jpg','cable',now(),now()),
('cable one arm reverse preacher curl','biceps',array['forearms']::text[],'beginner','isolation',array['Ajusta la máquina de cable de modo que la polea quede en la posición más baja.','Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.','Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott.','Mantén la espalda recta y el core activado durante todo el ejercicio.','Curva lentamente el antebrazo hacia el bíceps, manteniendo la parte superior del brazo inmóvil contra la almohadilla.','Haz una pausa por un momento en la parte más alta del movimiento, apretando el bíceps.','Baja lentamente la agarradera del cable de vuelta a la posición inicial.','Repite el número de repeticiones deseado.','Cambia de brazo y repite el ejercicio.']::text[],'Equipo: Polea',true,'1635','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1635-ZXnjcOQ.gif','https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1635-ZXnjcOQ.jpg','cable',now(),now())
on conflict (name) do update set
  catalog_id = coalesce(public.fc_exercises.catalog_id, excluded.catalog_id),
  gif_url = excluded.gif_url, image_url = excluded.image_url, equipment = excluded.equipment,
  instructions = case when coalesce(cardinality(public.fc_exercises.instructions), 0) = 0 then excluded.instructions else public.fc_exercises.instructions end,
  updated_at = now();

